/* Sirah events 1-44 (eras 0-4). [Malay, English]. Own-words retelling of Ar-Raheeq al-Makhtum. */
SIRAH.push(
{id:"s1",n:1,e:0,y:500,yt:["Sebelum 571 M","Before 571 CE"],pl:"arabia",sc:"arabia",
 w:["Zaman sebelum Islam","The time before Islam"],
 t:["Tanah Arab & kabilahnya","Arabia and its tribes"],
 f:["Semenanjung Arab dikelilingi Laut Merah, Teluk Parsi dan Laut Arab, dengan Syam di utaranya. Tanahnya kebanyakan padang pasir dan gunung batu, sehingga empayar besar ketika itu, Parsi dan Rom, tidak berminat menjajahnya. Keadaan ini menjadikannya bebas dan terpelihara.\nAhli sejarah membahagikan bangsa Arab kepada tiga: Arab yang telah lenyap seperti kaum 'Ad dan Thamud, Arab asli keturunan Qahtan di Yaman, dan Arab yang diarabkan, iaitu keturunan Nabi Ismail (a.s.) melalui Adnan. Quraisy berasal daripada cabang Adnan ini.\nKehidupan berasaskan kabilah. Setiap kabilah setia kepada ketuanya dan mempertahankan ahlinya. Makkah pula menjadi pusat perdagangan kerana Kaabah dan laluan kafilah ke Yaman dan Syam.",
   "The Arabian Peninsula is bordered by the Red Sea, the Persian Gulf and the Arabian Sea, with Syria to the north. It is mostly desert and rocky mountains, so the great empires of the day, Persia and Rome, had little wish to rule it. This left it free and protected.\nHistorians divide the Arabs into three: the Arabs who perished, like 'Ad and Thamud; the original Arabs descended from Qahtan in Yemen; and the Arabised Arabs descended from Ismail (a.s.) through 'Adnan. Quraysh came from this line of 'Adnan.\nLife was built on the tribe. Each tribe was loyal to its chief and defended its own. Makkah became a centre of trade because of the Kaabah and the caravan routes to Yemen and Syria."],
 l:[["Allah memilih tempat yang bebas daripada kuasa empayar untuk risalah terakhir.","Allah chose a land free of the empires for the final message."],["Semangat kabilah kemudiannya diganti dengan persaudaraan iman.","Tribal loyalty would later be replaced by the brotherhood of faith."]],
 ay:[{r:"Quraisy 106:1-2",ar:"لِإِيلَافِ قُرَيْشٍ ۝ إِيلَافِهِمْ رِحْلَةَ الشِّتَاءِ وَالصَّيْفِ",m:["Kerana kebiasaan aman Quraisy, iaitu kebiasaan mereka dalam perjalanan musim sejuk dan musim panas.","For the security of Quraysh, their security in the journeys of winter and summer."]}],
 s:"Location and Nature of Arab Tribes, p.8|Rahsia pemilihan Semenanjung Arab"},

{id:"s2",n:2,e:0,y:540,yt:["Sebelum 571 M","Before 571 CE"],pl:"makkah",sc:"market",
 w:["Zaman Jahiliyah","The age of ignorance"],
 t:["Agama & masyarakat Jahiliyah","Religion and society before Islam"],
 f:["Pada asalnya bangsa Arab mengikut agama Nabi Ibrahim (a.s.), iaitu menyembah Allah yang Esa. Lama-kelamaan ajaran itu dilupakan. Amr bin Luhay membawa berhala Hubal dari Syam dan meletakkannya di Kaabah. Akhirnya kira-kira 360 berhala mengelilingi Kaabah.\nMereka menilik nasib dengan anak panah, percaya kepada tukang tilik, dan sebahagian kabilah menanam anak perempuan hidup-hidup. Arak, judi dan riba berleluasa. Ada juga golongan Yahudi di Yathrib dan Khaibar, Nasrani di Najran, dan segelintir hanif yang tetap menyembah Allah.\nNamun mereka masih memiliki sifat mulia: pemurah kepada tetamu, menepati janji, berani dan cintakan kebebasan. Sifat-sifat inilah yang kemudiannya dibentuk oleh Islam.",
   "The Arabs first followed the religion of Ibrahim (a.s.), worshipping the One God. Over time that teaching was forgotten. 'Amr ibn Luhay brought the idol Hubal from Syria and set it up at the Kaabah. In the end some 360 idols stood around the Kaabah.\nThey sought omens with arrows, trusted soothsayers, and some tribes buried baby girls alive. Wine, gambling and usury were common. There were also Jews in Yathrib and Khaibar, Christians in Najran, and a few hanifs who still worshipped Allah alone.\nYet they had fine qualities too: generosity to guests, keeping their word, courage and a love of freedom. Islam would later shape these very qualities."],
 l:[["Kebenaran boleh dilupakan sedikit demi sedikit jika tidak dijaga.","Truth can be forgotten little by little if it is not guarded."],["Islam tidak membuang sifat baik sesuatu kaum, tetapi menyempurnakannya.","Islam does not discard a people's good traits; it perfects them."]],
 s:"Religions of the Arabs, p.22; Aspects of Pre-Islamic Arabian Society, p.28|"},

{id:"s3",n:3,e:0,y:-1900,yt:["Zaman Nabi Ibrahim (a.s.)","The time of Ibrahim (a.s.)"],pl:"makkah",sc:"kaabah",
 w:["Ribuan tahun sebelum Islam","Thousands of years before Islam"],
 t:["Nabi Ibrahim & Ismail (a.s.) membina Kaabah","Ibrahim and Ismail (a.s.) build the Kaabah"],
 f:["Dengan perintah Allah, Nabi Ibrahim (a.s.) membawa isterinya Hajar dan bayi mereka Ismail ke sebuah lembah kering tanpa tanaman di Makkah. Apabila bekalan air habis, Hajar berlari tujuh kali antara Bukit Safa dan Marwah mencari air, lalu Allah memancarkan air Zamzam. Kabilah Jurhum kemudian datang dan menetap di situ.\nApabila Ismail dewasa, Nabi Ibrahim kembali dan bersama-sama mereka meninggikan asas Kaabah, rumah pertama yang dibina untuk menyembah Allah. Sambil membina, mereka berdoa agar amalan mereka diterima dan agar Allah membangkitkan seorang rasul daripada keturunan mereka.\nDoa itu dimakbulkan dengan kelahiran Nabi Muhammad ﷺ daripada keturunan Ismail (a.s.).",
   "By Allah's command, Ibrahim (a.s.) brought his wife Hajar and their baby Ismail to a dry valley with no crops, at Makkah. When their water ran out, Hajar ran seven times between Safa and Marwah looking for water, and Allah made the spring of Zamzam flow. The tribe of Jurhum later came and settled there.\nWhen Ismail was grown, Ibrahim returned and together they raised the foundations of the Kaabah, the first house built for the worship of Allah. As they built, they prayed that their work be accepted and that Allah raise a messenger from their descendants.\nThat prayer was answered with the birth of Muhammad ﷺ from the line of Ismail (a.s.)."],
 l:[["Sa'i antara Safa dan Marwah mengingati usaha dan tawakal Hajar.","The walk between Safa and Marwah remembers Hajar's effort and trust."],["Nabi Muhammad ﷺ ialah jawapan kepada doa Nabi Ibrahim (a.s.).","Prophet Muhammad ﷺ is the answer to the prayer of Ibrahim (a.s.)."]],
 ay:[{r:"al-Baqarah 2:127",ar:"وَإِذْ يَرْفَعُ إِبْرَاهِيمُ الْقَوَاعِدَ مِنَ الْبَيْتِ وَإِسْمَاعِيلُ رَبَّنَا تَقَبَّلْ مِنَّا ۖ إِنَّكَ أَنتَ السَّمِيعُ الْعَلِيمُ",m:["Dan ingatlah ketika Ibrahim dan Ismail meninggikan asas Baitullah sambil berdoa: Wahai Tuhan kami, terimalah daripada kami. Sesungguhnya Engkaulah Yang Maha Mendengar lagi Maha Mengetahui.","And when Ibrahim was raising the foundations of the House, and Ismail: Our Lord, accept this from us. Indeed You are the All-Hearing, the All-Knowing."]}],
 p:[],s:"The Lineage and Family of Muhammad, p.32|"},

{id:"s4",n:4,e:0,y:545,yt:["Sebelum 571 M","Before 571 CE"],pl:"makkah",sc:"zamzam",
 w:["Zaman Abdul Muttalib","In 'Abdul-Muttalib's time"],
 t:["Abdul Muttalib menggali semula Zamzam","'Abdul-Muttalib re-digs Zamzam"],
 f:["Ketika kabilah Jurhum meninggalkan Makkah berabad-abad sebelumnya, mereka menimbus telaga Zamzam. Lama-kelamaan tiada siapa tahu di mana letaknya.\nAbdul Muttalib, datuk Rasulullah ﷺ dan ketua Bani Hasyim, bermimpi diperintah menggali Zamzam dan ditunjukkan tempatnya. Beliau menggalinya bersama anaknya al-Harith dan menemui semula air Zamzam, bersama barang yang pernah ditanam oleh Jurhum seperti pedang dan baju besi.\nQuraisy mahu berkongsi hak ke atas telaga itu, tetapi akhirnya Abdul Muttalib diiktiraf sebagai penjaganya. Sejak itu Bani Hasyim memberi minum kepada para jemaah haji, satu kemuliaan besar di Makkah.",
   "When the tribe of Jurhum left Makkah centuries earlier, they filled in the well of Zamzam. In time nobody knew where it lay.\n'Abdul-Muttalib, the Prophet's ﷺ grandfather and chief of Banu Hashim, saw in a dream that he should dig for Zamzam, and was shown the spot. He dug with his son al-Harith and found the water again, along with things Jurhum had buried, such as swords and armour.\nQuraysh wanted a share in the well, but in the end 'Abdul-Muttalib was accepted as its keeper. From then on Banu Hashim gave water to the pilgrims, a great honour in Makkah."],
 l:[["Allah memuliakan keluarga Rasulullah ﷺ sebelum Baginda lahir lagi.","Allah honoured the Prophet's ﷺ family even before his birth."],["Memberi minum kepada tetamu Allah ialah satu kemuliaan.","Giving water to the guests of Allah is an honour."]],
 p:["abdulmuttalib"],s:"The Prophetic Family, p.32|"},

{id:"s5",n:5,e:0,y:560,yt:["Sebelum 571 M","Before 571 CE"],pl:"makkah",sc:"kaabah2",
 w:["Zaman Abdul Muttalib","In 'Abdul-Muttalib's time"],
 t:["Nazar Abdul Muttalib & tebusan Abdullah","'Abdul-Muttalib's vow and 'Abdullah's ransom"],
 f:["Ketika menggali Zamzam, Abdul Muttalib hanya mempunyai seorang anak lelaki. Beliau bernazar, jika dikurniakan sepuluh anak lelaki yang dewasa, beliau akan mengorbankan seorang daripada mereka di Kaabah.\nApabila nazar itu tertunai, beliau mencabut undi dan undi jatuh kepada Abdullah, anak yang paling disayanginya. Quraisy dan bapa-bapa saudara Abdullah membantah. Mereka merujuk kepada seorang wanita yang dikenali bijaksana. Beliau menyuruh mereka mengundi antara Abdullah dan sepuluh ekor unta, dan menambah sepuluh ekor setiap kali undi jatuh kepada Abdullah.\nUndi akhirnya jatuh kepada unta apabila jumlahnya mencecah seratus ekor. Unta-unta itu disembelih dan Abdullah diselamatkan. Tidak lama kemudian Abdullah berkahwin dengan Aminah binti Wahb dari Bani Zuhrah.",
   "When he was digging Zamzam, 'Abdul-Muttalib had only one son. He vowed that if he were given ten grown sons, he would sacrifice one of them at the Kaabah.\nWhen that came true, he drew lots and the lot fell on 'Abdullah, his most beloved son. Quraysh and 'Abdullah's uncles objected. They asked a woman known for her wisdom. She told them to draw lots between 'Abdullah and ten camels, adding ten camels each time the lot fell on 'Abdullah.\nThe lot finally fell on the camels when they reached one hundred. The camels were sacrificed and 'Abdullah was spared. Soon after, 'Abdullah married Aminah bint Wahb of Banu Zuhrah."],
 l:[["Nazar perlu difikir dengan teliti sebelum dibuat.","A vow should be thought about carefully before it is made."],["Allah memelihara bapa Rasulullah ﷺ supaya Baginda lahir.","Allah preserved the Prophet's ﷺ father so that he would be born."]],
 p:["abdulmuttalib","abdullah","aminah"],s:"The Prophetic Family, p.32|"},

{id:"s6",n:6,e:0,y:570.5,pl:"madinah",sc:"sunset",
 w:["Sebelum kelahiran Baginda","Before the Prophet's birth"],
 t:["Abdullah wafat di Yathrib","'Abdullah dies in Yathrib"],
 f:["Tidak lama selepas perkahwinannya dengan Aminah, Abdullah pergi berdagang ke Syam. Dalam perjalanan pulang beliau jatuh sakit dan berhenti di Yathrib, di sisi saudara-mara sebelah neneknya dari Bani an-Najjar. Di sanalah beliau wafat ketika berusia kira-kira 25 tahun, sebelum puteranya lahir.\nAbdullah meninggalkan harta yang sedikit: lima ekor unta, sekumpulan kambing dan seorang hamba perempuan bernama Barakah, yang dikenali sebagai Ummu Aiman. Ummu Aiman kemudiannya menjaga Rasulullah ﷺ dengan penuh kasih.\nMaka Nabi Muhammad ﷺ lahir sebagai anak yatim, satu permulaan hidup yang mendekatkan Baginda kepada orang-orang yang lemah.",
   "Not long after marrying Aminah, 'Abdullah went to trade in Syria. On the way home he fell ill and stopped in Yathrib, with his grandmother's family of Banu an-Najjar. He died there at about 25 years of age, before his son was born.\n'Abdullah left very little: five camels, a small flock of sheep and a slave girl named Barakah, known as Umm Ayman. Umm Ayman later cared for the Prophet ﷺ with great love.\nSo Muhammad ﷺ was born an orphan, a start in life that kept him close to the weak."],
 l:[["Allah sendiri yang mendidik dan melindungi Rasul-Nya.","Allah Himself raised and protected His Messenger."],["Anak yatim mempunyai tempat istimewa dalam Islam.","Orphans have a special place in Islam."]],
 o:["Sebahagian riwayat menyebut Abdullah wafat beberapa bulan selepas kelahiran Baginda. Pendapat yang lebih masyhur ialah sebelum kelahiran.","Some reports say 'Abdullah died a few months after the birth. The better-known view is that he died before it."],
 p:["abdullah"],s:"The Prophetic Family, p.32|"},

{id:"s7",n:7,e:0,m:1,y:571.15,pl:"makkah",sc:"elephant",
 w:["Muharram, Tahun Gajah (akhir Februari atau awal Mac 571)","Muharram, the Year of the Elephant (late February or early March 571)"],
 t:["Tahun Gajah: Abrahah & burung Ababil","The Year of the Elephant"],
 f:["Abrahah, gabenor Habsyah di Yaman, membina sebuah gereja besar di San'a untuk mengalihkan orang Arab daripada berhaji ke Kaabah. Apabila seorang lelaki Arab mencemarkan gereja itu, Abrahah bersumpah akan meruntuhkan Kaabah. Beliau mara dengan tentera seramai kira-kira 60,000 orang bersama beberapa ekor gajah.\nDi pinggir Makkah tenteranya merampas unta Abdul Muttalib. Abdul Muttalib datang menuntut untanya sahaja. Apabila Abrahah hairan, beliau menjawab: “Aku tuan unta-unta itu. Rumah itu ada Tuhannya yang akan melindunginya.” Penduduk Makkah berlindung di bukit-bukit.\nApabila tentera itu bergerak, gajah mereka berlutut dan enggan menuju ke Kaabah. Allah menghantar kawanan burung yang membawa batu-batu dari tanah yang dibakar. Tentera itu binasa di lembah Muhassir, antara Muzdalifah dan Mina. Peristiwa ini berlaku kira-kira 50 hari sebelum kelahiran Rasulullah ﷺ.",
   "Abrahah, the Abyssinian governor of Yemen, built a great church in San'a to draw the Arabs away from pilgrimage to the Kaabah. When an Arab man defiled the church, Abrahah swore to destroy the Kaabah. He marched with an army of about 60,000 and several elephants.\nOn the edge of Makkah his soldiers seized 'Abdul-Muttalib's camels. 'Abdul-Muttalib came and asked only for his camels. When Abrahah was surprised, he said: “I am the owner of the camels. The House has a Lord who will protect it.” The people of Makkah took shelter in the hills.\nWhen the army moved, the lead elephant knelt and refused to face the Kaabah. Allah sent flocks of birds carrying stones of baked clay. The army was destroyed in the valley of Muhassir, between Muzdalifah and Mina. This happened about 50 days before the Prophet ﷺ was born."],
 k:["Seorang raja bernama Abrahah datang dengan gajah-gajah untuk meruntuhkan Kaabah. Allah menghantar burung-burung Ababil yang membawa batu-batu kecil, dan tentera itu kalah. Kaabah selamat, dan tidak lama kemudian Nabi Muhammad ﷺ lahir.","A ruler named Abrahah came with elephants to destroy the Kaabah. Allah sent the Ababil birds carrying small stones, and the army was beaten. The Kaabah was safe, and soon after, Prophet Muhammad ﷺ was born."],
 l:[["Allah sendiri yang menjaga Rumah-Nya.","Allah Himself guards His House."],["Kekuatan tentera tidak bermakna di hadapan kehendak Allah.","Military might means nothing before the will of Allah."],["Peristiwa ini menjadikan Quraisy dihormati di seluruh Arab, sebagai persiapan untuk risalah.","It made Quraysh respected across Arabia, preparing the way for the message."]],
 ay:[{kid:1,r:"al-Fil 105:1",ar:"أَلَمْ تَرَ كَيْفَ فَعَلَ رَبُّكَ بِأَصْحَابِ الْفِيلِ",m:["Tidakkah engkau melihat bagaimana Tuhanmu bertindak terhadap tentera bergajah?","Have you not seen how your Lord dealt with the people of the elephant?"]}],
 p:["abrahah","abdulmuttalib"],s:"Rulership in Yemen, p.14|"},

{id:"s8",n:8,e:1,m:1,y:571.3,age:"",pl:"makkah",sc:"birth",
 w:["Isnin, 9 Rabiulawal, Tahun Gajah (20 atau 22 April 571)","Monday, 9 Rabi' al-Awwal, the Year of the Elephant (20 or 22 April 571)"],
 t:["Kelahiran Rasulullah ﷺ","The birth of the Prophet ﷺ"],
 f:["Nabi Muhammad ﷺ lahir di kawasan Bani Hasyim di Makkah pada pagi hari Isnin, 9 Rabiulawal Tahun Gajah, bersamaan 20 atau 22 April 571. Tarikh ini berdasarkan kajian al-Mansurpuri dan ahli falak Mahmud Pasya.\nAminah menceritakan bahawa ketika melahirkan Baginda, keluar cahaya daripadanya yang menerangi istana-istana di Syam. Berita kelahiran disampaikan kepada Abdul Muttalib, yang sangat gembira. Beliau membawa cucunya masuk ke Kaabah, berdoa dan bersyukur kepada Allah, lalu menamakannya Muhammad, nama yang jarang digunakan oleh orang Arab ketika itu. Pada hari ketujuh Baginda dikhatankan mengikut adat.\nBaginda lahir sebagai anak yatim, dan kemudian menjadi rahmat bagi sekalian alam.",
   "Muhammad ﷺ was born in the quarter of Banu Hashim in Makkah on Monday morning, 9 Rabi' al-Awwal in the Year of the Elephant, that is 20 or 22 April 571. This date follows the research of al-Mansurpuri and the astronomer Mahmud Pasha.\nAminah related that when she gave birth, a light came from her that lit up the palaces of Syria. The news reached 'Abdul-Muttalib, who was overjoyed. He carried his grandson into the Kaabah, prayed and thanked Allah, and named him Muhammad, a name rarely used by the Arabs then. On the seventh day he was circumcised, as was the custom.\nHe was born an orphan, and became a mercy to all the worlds."],
 k:["Nabi Muhammad ﷺ lahir di Makkah pada hari Isnin. Ibunya bernama Aminah, dan bapanya Abdullah sudah wafat sebelum Baginda lahir. Datuknya, Abdul Muttalib, sangat gembira dan memberinya nama Muhammad, yang bermaksud ‘yang terpuji’.","Prophet Muhammad ﷺ was born in Makkah on a Monday. His mother was Aminah, and his father 'Abdullah had died before he was born. His grandfather 'Abdul-Muttalib was overjoyed and named him Muhammad, which means ‘the praised one’."],
 l:[["Rasulullah ﷺ berpuasa pada hari Isnin kerana itu hari kelahirannya.","The Prophet ﷺ fasted on Mondays because it was the day of his birth."],["Kelahiran Baginda ialah rahmat untuk seluruh alam.","His birth was a mercy for all the worlds."]],
 hd:[{r:"Sahih Muslim 1162",m:["Apabila ditanya tentang puasa hari Isnin, Baginda bersabda: “Itulah hari aku dilahirkan dan hari aku diutus (atau wahyu diturunkan kepadaku).”","Asked about fasting on Monday, he said: “That is the day I was born, and the day I was sent (or revelation came to me).”"]}],
 o:["Ramai di Malaysia menyambut Maulidur Rasul pada 12 Rabiulawal, mengikut riwayat Ibn Ishaq.","Many in Malaysia celebrate the Prophet's birthday on 12 Rabi' al-Awwal, following the report of Ibn Ishaq."],
 p:["aminah","abdulmuttalib"],s:"His Birth, p.37|Kelahiran Rasulullah dan empat puluh tahun sebelum pengutusan"},

{id:"s9",n:9,e:1,y:571.32,age:"",pl:"makkah",sc:"birth",
 w:["Hari-hari pertama selepas kelahiran","The first days after the birth"],
 t:["Disusukan Thuwaibah","Nursed by Thuwaibah"],
 f:["Selepas ibunya, wanita pertama yang menyusukan Rasulullah ﷺ ialah Thuwaibah, hamba Abu Lahab. Ketika itu Thuwaibah sedang menyusukan anaknya sendiri, Masruh. Sebelum itu beliau pernah menyusukan Hamzah bin Abdul Muttalib, dan selepas itu Abu Salamah.\nKerana itu Hamzah, bapa saudara Baginda, juga merupakan saudara susuan Baginda. Rasulullah ﷺ sentiasa menghormati Thuwaibah dan menghantar hadiah kepadanya sepanjang hidupnya.",
   "After his mother, the first woman to nurse the Prophet ﷺ was Thuwaibah, a slave of Abu Lahab. She was nursing her own son, Masruh, at the time. Earlier she had nursed Hamzah ibn 'Abdul-Muttalib, and later she nursed Abu Salamah.\nSo Hamzah, his uncle, was also his foster brother. The Prophet ﷺ always honoured Thuwaibah and sent her gifts for as long as she lived."],
 l:[["Jasa orang yang pernah berbuat baik kepada kita patut dikenang.","Those who were kind to us deserve to be remembered."],["Hubungan susuan mewujudkan ikatan keluarga dalam Islam.","Nursing creates family ties in Islam."]],
 p:["hamzah"],s:"Babyhood, p.37|Kelahiran Rasulullah dan empat puluh tahun sebelum pengutusan"},

{id:"s10",n:10,e:1,m:1,y:571.4,age:"0–4",pl:"banisaad",sc:"tents",
 w:["571 hingga kira-kira 575","571 to about 575"],
 t:["Bersama Halimah di perkampungan Bani Sa'd","With Halimah among Banu Sa'd"],
 f:["Bangsawan Makkah biasa menghantar bayi mereka kepada keluarga Badwi supaya membesar sihat dan fasih berbahasa Arab. Pada tahun kemarau itu, wanita-wanita Bani Sa'd datang ke Makkah mencari bayi untuk disusukan. Tiada siapa mahu mengambil Muhammad ﷺ kerana Baginda anak yatim.\nHalimah as-Sa'diyyah, yang tidak mendapat bayi lain, akhirnya mengambil Baginda. Serta-merta susunya cukup untuk Baginda dan anaknya sendiri. Unta tua mereka mengeluarkan susu, keldainya yang kurus menjadi laju, dan kambing-kambing mereka pulang dengan kenyang ketika kawanan orang lain lapar.\nSelepas dua tahun, Halimah memujuk Aminah supaya membenarkan Baginda tinggal lebih lama kerana bimbang wabak di Makkah. Baginda tinggal bersama mereka hingga berusia empat atau lima tahun.",
   "The nobles of Makkah used to send their babies to Bedouin families so they would grow up healthy and speak pure Arabic. In that year of drought, women of Banu Sa'd came to Makkah looking for babies to nurse. Nobody wanted Muhammad ﷺ, because he was an orphan.\nHalimah as-Sa'diyyah, who found no other baby, finally took him. At once she had enough milk for him and her own son. Their old she-camel gave milk, her thin donkey became swift, and their sheep came home full while other flocks went hungry.\nAfter two years, Halimah persuaded Aminah to let him stay longer, fearing an illness in Makkah. He stayed with them until he was four or five."],
 k:["Ketika bayi, Nabi ﷺ tinggal di padang pasir bersama ibu susuannya, Halimah. Sejak Baginda datang, kambing dan unta Halimah menjadi gemuk dan banyak susu. Halimah tahu bayi ini membawa keberkatan.","As a baby, the Prophet ﷺ lived in the desert with his nursing mother, Halimah. From the day he came, Halimah's sheep and camels grew strong and gave plenty of milk. Halimah knew this baby brought blessings."],
 l:[["Keberkatan datang bersama orang yang dipilih Allah.","Blessing comes with those whom Allah has chosen."],["Membesar di padang pasir membentuk tubuh yang kuat dan bahasa yang fasih.","Growing up in the desert gave him a strong body and pure speech."]],
 p:["halimah"],s:"Babyhood, p.37|Di persada Bani Sa'ad"},

{id:"s11",n:11,e:1,y:575,age:"4–5",pl:"banisaad",sc:"valley",
 w:["Kira-kira 575","About 575"],
 t:["Peristiwa pembelahan dada","The opening of the chest"],
 f:["Ketika Rasulullah ﷺ sedang bermain bersama kanak-kanak lain di perkampungan Bani Sa'd, malaikat Jibril datang, membaringkan Baginda dan membelah dadanya. Jibril mengeluarkan hatinya, membuang seketul darah beku daripadanya dan berkata: “Inilah bahagian syaitan daripadamu.” Kemudian hatinya dibasuh dengan air Zamzam di dalam bekas emas dan dikembalikan ke tempatnya.\nKanak-kanak itu berlari kepada Halimah sambil menjerit bahawa Muhammad telah dibunuh. Apabila mereka sampai, Baginda selamat, cuma wajahnya pucat. Halimah menjadi risau, lalu memulangkan Baginda kepada ibunya di Makkah.",
   "While the Prophet ﷺ was playing with other children among Banu Sa'd, the angel Jibril came, laid him down and opened his chest. He took out his heart, removed a clot of blood from it and said: “This is Satan's share of you.” Then he washed the heart with Zamzam water in a golden basin and returned it to its place.\nThe children ran to Halimah crying that Muhammad had been killed. When they arrived, he was safe, only pale. Halimah became worried and returned him to his mother in Makkah."],
 l:[["Allah menyucikan Rasul-Nya sejak kecil.","Allah purified His Messenger from childhood."]],
 hd:[{r:"Sahih Muslim 162",m:["Anas (r.a.) meriwayatkan peristiwa Jibril membelah dada Rasulullah ﷺ ketika Baginda bermain bersama kanak-kanak.","Anas (r.a.) narrated how Jibril opened the Prophet's ﷺ chest while he was playing with other children."]}],
 p:["halimah"],s:"Babyhood, p.37|Di persada Bani Sa'ad"},

{id:"s12",n:12,e:1,y:577,age:6,pl:"abwa",sc:"abwa",
 w:["Kira-kira 577","About 577"],
 t:["Aminah wafat di Abwa'","Aminah dies at Abwa'"],
 f:["Rasulullah ﷺ tinggal bersama ibunya hingga berusia enam tahun. Aminah ingin menziarahi kubur suaminya di Yathrib. Beliau berangkat bersama puteranya, pembantunya Ummu Aiman dan Abdul Muttalib, sejauh kira-kira 500 kilometer. Mereka tinggal di sana selama sebulan.\nDalam perjalanan pulang, Aminah jatuh sakit dan wafat di Abwa', antara Makkah dan Madinah. Ummu Aiman membawa Baginda pulang ke Makkah. Pada usia enam tahun, Baginda kehilangan kedua ibu bapanya.",
   "The Prophet ﷺ lived with his mother until he was six. Aminah wished to visit her husband's grave in Yathrib. She set out with her son, her helper Umm Ayman and 'Abdul-Muttalib, a journey of about 500 kilometres. They stayed there a month.\nOn the way home, Aminah fell ill and died at Abwa', between Makkah and Madinah. Umm Ayman brought the boy back to Makkah. At six years old, he had lost both his parents."],
 l:[["Ujian kehilangan membentuk hati yang lembut kepada orang yang bersedih.","The pain of loss shaped a heart gentle to the grieving."],["Allah tidak pernah meninggalkan Rasul-Nya tanpa penjaga.","Allah never left His Messenger without a guardian."]],
 p:["aminah"],s:"Back to His Passionate Mother, p.37|Ke pangkuan ibunya yang penyayang"},

{id:"s13",n:13,e:1,y:579,age:8,pl:"makkah",sc:"kaabah",
 w:["577 hingga 579","577 to 579"],
 t:["Dijaga datuk, Abdul Muttalib","Cared for by his grandfather"],
 f:["Selepas Aminah wafat, Abdul Muttalib menjaga cucunya dengan kasih yang lebih daripada kepada anak-anaknya sendiri. Satu hamparan dibentangkan untuk Abdul Muttalib di bawah bayang Kaabah. Anak-anaknya duduk di sekeliling dan tiada siapa berani duduk di atasnya kerana menghormatinya. Namun Muhammad ﷺ kecil selalu datang dan duduk di atas hamparan itu. Apabila bapa-bapa saudaranya hendak mengangkatnya, Abdul Muttalib berkata: “Biarkan dia. Demi Allah, anak ini akan mempunyai kedudukan yang besar.”\nAbdul Muttalib wafat ketika Rasulullah ﷺ berusia lapan tahun, dua bulan dan sepuluh hari. Sebelum wafat, beliau mengamanahkan Baginda kepada Abu Talib, abang kandung Abdullah.",
   "After Aminah's death, 'Abdul-Muttalib cared for his grandson with more love than for his own sons. A mat was spread for 'Abdul-Muttalib in the shade of the Kaabah. His sons sat around it and none dared sit on it out of respect. Yet the young Muhammad ﷺ would come and sit right on it. When his uncles tried to move him, 'Abdul-Muttalib said: “Leave him. By Allah, this boy will have a great standing.”\n'Abdul-Muttalib died when the Prophet ﷺ was eight years, two months and ten days old. Before he died, he entrusted the boy to Abu Talib, the full brother of 'Abdullah."],
 l:[["Kasih sayang orang tua membina keyakinan kanak-kanak.","An elder's love builds a child's confidence."]],
 p:["abdulmuttalib","abutalib"],s:"To His Compassionate Grandfather, p.37|Ke pangkuan datuk pembelas kasihan"},

{id:"s14",n:14,e:1,y:579.2,age:8,pl:"makkah",sc:"birth",
 w:["Dari 579","From 579"],
 t:["Di bawah jagaan Abu Talib","Abu Talib takes him in"],
 f:["Abu Talib tidak kaya dan mempunyai ramai anak, tetapi beliau menyayangi anak saudaranya lebih daripada anak-anaknya sendiri. Rasulullah ﷺ tidur di sisinya dan pergi ke mana-mana bersamanya. Abu Talib kekal menjaga dan melindungi Baginda selama lebih empat puluh tahun.\nDiriwayatkan bahawa ketika Makkah dilanda kemarau, Abu Talib membawa Muhammad ﷺ yang masih kecil ke Kaabah dan memohon hujan. Tidak lama kemudian hujan turun dengan lebat. Abu Talib kemudian memuji anak saudaranya dalam syair sebagai wajah yang dengannya hujan dipohon.",
   "Abu Talib was not rich and had many children, yet he loved his nephew more than his own children. The Prophet ﷺ slept beside him and went everywhere with him. Abu Talib went on caring for and protecting him for more than forty years.\nIt is reported that when Makkah suffered a drought, Abu Talib took the young Muhammad ﷺ to the Kaabah and prayed for rain. Soon heavy rain fell. Abu Talib later praised his nephew in a poem as the face through which rain is sought."],
 l:[["Allah sentiasa menyediakan pelindung untuk anak yatim.","Allah always provides a protector for the orphan."]],
 ay:[{r:"ad-Duha 93:6",ar:"أَلَمْ يَجِدْكَ يَتِيمًا فَآوَىٰ",m:["Bukankah Dia mendapatimu seorang yatim, lalu Dia melindungimu?","Did He not find you an orphan and give you shelter?"]}],
 p:["abutalib"],s:"To His Compassionate Grandfather, p.37|Ke pangkuan datuk pembelas kasihan"},

{id:"s15",n:15,e:1,y:583,age:12,pl:"busra",sc:"caravan",
 w:["Kira-kira 583","About 583"],
 t:["Ke Syam & rahib Bahira","The journey to Syria and the monk Bahira"],
 f:["Ketika berusia dua belas tahun, Rasulullah ﷺ mengikut Abu Talib dalam kafilah dagang ke Syam. Apabila mereka berhenti di Busra, seorang rahib bernama Bahira keluar menemui kafilah itu, sesuatu yang tidak pernah dilakukannya sebelum ini. Beliau memegang tangan Baginda dan berkata: “Inilah penghulu sekalian alam. Allah akan mengutusnya sebagai rahmat untuk sekalian alam.”\nBahira menyebut bahawa pokok dan batu tunduk ketika kafilah itu datang, dan beliau mengenali tanda kenabian di antara bahu Baginda. Beliau menasihati Abu Talib supaya membawa Baginda pulang kerana bimbang Baginda diapa-apakan oleh orang Rom. Abu Talib pun menghantar Baginda pulang ke Makkah.",
   "When he was twelve, the Prophet ﷺ travelled with Abu Talib in a trading caravan to Syria. When they stopped at Busra, a monk named Bahira came out to meet the caravan, something he had never done before. He took the boy's hand and said: “This is the master of the worlds. Allah will send him as a mercy to the worlds.”\nBahira said the trees and stones had bowed as the caravan came, and he recognised the seal of prophethood between the boy's shoulders. He advised Abu Talib to take him home, fearing the Romans might harm him. So Abu Talib sent him back to Makkah."],
 l:[["Ahli kitab yang jujur mengenali tanda-tanda kenabian.","Honest people of the scripture recognised the signs of prophethood."]],
 hd:[{r:"Jami' at-Tirmidhi 3620",m:["Abu Musa al-Asy'ari (r.a.) meriwayatkan kisah Abu Talib membawa Baginda ke Syam dan pertemuan dengan rahib itu.","Abu Musa al-Ash'ari (r.a.) narrated how Abu Talib took him to Syria and the meeting with the monk."]}],
 p:["abutalib","bahira"],s:"Bahira, the Monk, p.37|"},

{id:"s16",n:16,e:2,y:586,age:15,pl:"makkah",sc:"valley",
 w:["Kira-kira 586","About 586"],
 t:["Perang Fijar","The Fijar wars"],
 f:["Ketika Rasulullah ﷺ berusia sekitar lima belas tahun, meletus peperangan antara Quraisy bersama Kinanah menentang kabilah Qais 'Ailan. Ia dinamakan Fijar, iaitu ‘pencabulan’, kerana berlaku dalam bulan-bulan haram yang sepatutnya bebas daripada peperangan.\nBaginda hadir bersama bapa-bapa saudaranya dan membantu dengan mengumpul dan menghulurkan anak panah kepada mereka. Peperangan itu berakhir dengan perdamaian. Ia memberi Baginda pengalaman awal tentang buruknya pertumpahan darah antara kabilah.",
   "When the Prophet ﷺ was about fifteen, war broke out between Quraysh with Kinanah and the tribe of Qays 'Aylan. It was called Fijar, ‘sacrilege’, because it was fought in the sacred months when fighting was forbidden.\nHe was there with his uncles and helped by gathering arrows and handing them to them. The war ended in peace. It gave him an early taste of how terrible bloodshed between tribes could be."],
 l:[["Kehormatan masa dan tempat yang suci perlu dijaga.","Sacred times and places must be honoured."]],
 p:["abutalib"],s:"The Sacrilegious Wars, p.37|Peperangan al-Fujjar"},

{id:"s17",n:17,e:2,m:1,y:586.5,age:15,pl:"makkah",sc:"arqam",
 w:["Zulkaedah, selepas Perang Fijar","Dhul-Qa'dah, after the Fijar wars"],
 t:["Perjanjian al-Fudul","The Fudul pact for justice"],
 f:["Seorang pedagang dari Zubaid menjual barangan kepada al-'As bin Wa'il, seorang pembesar Quraisy, tetapi al-'As enggan membayar. Pedagang itu merayu kepada orang ramai di Makkah. Beberapa puak Quraisy, antaranya Bani Hasyim, Bani Muttalib, Bani Asad, Bani Zuhrah dan Bani Taim, berkumpul di rumah Abdullah bin Jud'an. Mereka berikrar untuk membela sesiapa sahaja yang dizalimi di Makkah, sama ada penduduk tempatan atau orang luar, sehingga haknya dikembalikan. Mereka terus pergi kepada al-'As dan mengambil hak pedagang itu.\nRasulullah ﷺ menghadiri perjanjian ini. Selepas menjadi nabi, Baginda berkata bahawa Baginda tidak akan menukar penyertaannya dalam perjanjian itu dengan unta merah sekalipun, dan jika diajak kepadanya dalam Islam, Baginda tetap akan menyahutnya.",
   "A trader from Zubaid sold goods to al-'As ibn Wa'il, a Quraysh nobleman, but al-'As refused to pay. The trader appealed to the people of Makkah. Several clans of Quraysh, among them Banu Hashim, Banu al-Muttalib, Banu Asad, Banu Zuhrah and Banu Taym, met in the house of 'Abdullah ibn Jud'an. They pledged to stand with anyone wronged in Makkah, local or stranger, until his right was restored. They went straight to al-'As and took back the trader's due.\nThe Prophet ﷺ was present at this pact. After he became a prophet, he said he would not exchange his part in it even for red camels, and that if he were called to such a pact in Islam, he would answer."],
 k:["Ketika muda, Nabi ﷺ menyertai satu janji bersama pembesar Makkah: mereka akan membantu sesiapa sahaja yang dianiaya. Nabi ﷺ sangat suka kepada keadilan sejak muda.","As a young man, the Prophet ﷺ joined a promise with the leaders of Makkah: they would help anyone treated unfairly. He loved justice from a young age."],
 l:[["Menolong orang yang dizalimi ialah nilai yang dipuji Islam walaupun bermula sebelum Islam.","Helping the wronged is praised by Islam, even when it began before Islam."],["Keadilan untuk semua, termasuk orang asing.","Justice is for everyone, including strangers."]],
 s:"Al-Fudoul Confederacy, p.37|Perjanjian al-Fudul"},

{id:"s18",n:18,e:2,y:590,age:"15–24",pl:"makkah",sc:"market",
 w:["Kira-kira 586 hingga 595","About 586 to 595"],
 t:["Menggembala kambing & berniaga: al-Amin","Shepherd and trader: al-Amin"],
 f:["Pada masa mudanya Rasulullah ﷺ menggembala kambing, pertama untuk Bani Sa'd dan kemudian untuk penduduk Makkah dengan upah yang sedikit. Kemudian Baginda berniaga. Baginda dikenali dengan sifat jujur, amanah, menepati janji dan bersih daripada perkara keji.\nBaginda tidak pernah menyembah berhala, tidak minum arak dan tidak menghadiri perayaan berhala. Penduduk Makkah menggelarnya ‘al-Amin’, orang yang dipercayai, dan mereka menyimpan barang berharga mereka di tangannya.",
   "In his youth the Prophet ﷺ herded sheep, first for Banu Sa'd and then for the people of Makkah for a small wage. Later he turned to trade. He was known for being truthful, trustworthy, keeping his word and staying clear of anything shameful.\nHe never worshipped idols, never drank wine and never joined the idol festivals. The people of Makkah called him ‘al-Amin’, the trustworthy one, and left their valuables in his care."],
 l:[["Menggembala kambing mendidik sabar dan rasa tanggungjawab.","Herding sheep teaches patience and responsibility."],["Kejujuran ialah asas dakwah.","Honesty is the foundation of calling others."]],
 hd:[{r:"Sahih al-Bukhari 2262",m:["Baginda bersabda: “Allah tidak mengutus seorang nabi melainkan dia pernah menggembala kambing.” Baginda juga menggembala untuk penduduk Makkah dengan upah beberapa qirat.","He said: “Allah never sent a prophet who did not herd sheep.” He herded for the people of Makkah for a few qirats."]}],
 s:"Muhammad's Early Job, p.37|Hidup penuh keperitan"},

{id:"s19",n:19,e:2,y:595,age:25,pl:"busra",sc:"caravan",
 w:["Kira-kira 595","About 595"],
 t:["Berniaga untuk Khadijah ke Syam","Trading for Khadijah in Syria"],
 f:["Khadijah binti Khuwailid ialah seorang wanita bangsawan dan saudagar yang kaya. Beliau mengupah lelaki untuk membawa barang dagangannya. Apabila mendengar tentang kejujuran Muhammad ﷺ, beliau menawarkan Baginda membawa barangannya ke Syam dengan bayaran lebih tinggi daripada orang lain, ditemani pembantunya Maisarah.\nPerniagaan itu mendapat keuntungan yang besar. Maisarah pulang dengan cerita tentang akhlak Baginda yang mulia, kejujurannya dan cara Baginda berurusan. Khadijah sangat kagum dengan apa yang didengarnya.",
   "Khadijah bint Khuwaylid was a noble woman and a wealthy merchant. She hired men to carry her goods. Hearing of Muhammad's ﷺ honesty, she offered him her goods to take to Syria for more pay than others, with her servant Maysarah.\nThe trade made a great profit. Maysarah came back with stories of his noble manners, his honesty and the way he dealt with people. Khadijah was deeply impressed by what she heard."],
 l:[["Peniaga yang jujur membawa keberkatan.","An honest trader brings blessing."]],
 p:["khadijah","maisarah"],s:"His Marriage to Khadijah, p.37|Hidup penuh keperitan"},

{id:"s20",n:20,e:2,m:1,y:595.5,age:25,pl:"makkah",sc:"birth",
 w:["Dua bulan selepas pulang dari Syam","Two months after returning from Syria"],
 t:["Perkahwinan dengan Khadijah (r.a.)","Marriage to Khadijah (r.a.)"],
 f:["Khadijah melihat dalam diri Muhammad ﷺ akhlak yang tiada pada orang lain. Walaupun ramai pembesar Quraisy pernah melamarnya, beliau menolak mereka. Beliau menghantar sahabatnya Nafisah binti Munyah untuk bertanya sama ada Baginda sudi berkahwin dengannya. Baginda bersetuju, dan bapa-bapa saudaranya pergi meminang.\nPerkahwinan berlangsung dua bulan selepas Baginda pulang dari Syam, dengan mahar dua puluh ekor unta. Ketika itu Rasulullah ﷺ berusia 25 tahun dan Khadijah 40 tahun. Beliau wanita Quraisy yang paling mulia keturunannya, paling kaya dan paling bijaksana.\nSelama Khadijah hidup, Rasulullah ﷺ tidak berkahwin dengan wanita lain.",
   "Khadijah saw in Muhammad ﷺ a character found in no one else. Though many Quraysh nobles had proposed to her, she had refused them. She sent her friend Nafisah bint Munyah to ask whether he would marry her. He agreed, and his uncles went to make the proposal.\nThe marriage took place two months after his return from Syria, with a dowry of twenty camels. The Prophet ﷺ was 25 and Khadijah was 40. She was the noblest woman of Quraysh in lineage, the wealthiest and the wisest.\nAs long as Khadijah lived, he married no one else."],
 k:["Khadijah ialah seorang wanita yang baik hati dan bijak berniaga. Beliau kagum dengan kejujuran Nabi ﷺ dan mereka pun berkahwin. Mereka hidup bahagia dan saling menyokong.","Khadijah was a kind woman and a wise trader. She admired the Prophet's ﷺ honesty, and they married. They lived happily and supported each other."],
 l:[["Akhlak ialah ukuran utama dalam memilih pasangan.","Character is the main measure in choosing a spouse."],["Khadijah menjadi penyokong terbesar Rasulullah ﷺ.","Khadijah became the Prophet's ﷺ greatest supporter."]],
 o:["Ada riwayat lain yang menyebut usia Khadijah ketika berkahwin ialah 28 tahun.","Another report gives Khadijah's age at the marriage as 28."],
 p:["khadijah"],s:"His Marriage to Khadijah, p.37|Hidup penuh keperitan"},

{id:"s21",n:21,e:2,y:600,age:"25–40",pl:"makkah",sc:"family",
 w:["595 hingga 610","595 to 610"],
 t:["Anak-anak Baginda","His children"],
 f:["Khadijah melahirkan anak-anak Rasulullah ﷺ kecuali Ibrahim. Mereka ialah al-Qasim (kerana itu Baginda digelar Abu al-Qasim), Zainab, Ruqayyah, Ummu Kalthum, Fatimah dan Abdullah, yang digelar at-Tayyib dan at-Tahir.\nSemua anak lelaki Baginda wafat ketika kecil. Anak-anak perempuan Baginda sempat hidup hingga datangnya Islam. Mereka semua memeluk Islam dan berhijrah. Semuanya wafat semasa hayat Baginda kecuali Fatimah, yang wafat kira-kira enam bulan selepas Baginda.",
   "Khadijah bore all the Prophet's ﷺ children except Ibrahim. They were al-Qasim (which is why he was called Abu al-Qasim), Zaynab, Ruqayyah, Umm Kulthum, Fatimah and 'Abdullah, who was called at-Tayyib and at-Tahir.\nAll his sons died as small children. His daughters lived to see Islam. They all accepted it and emigrated. All of them died in his lifetime except Fatimah, who died about six months after him."],
 l:[["Rasulullah ﷺ juga diuji dengan kematian anak-anak.","The Prophet ﷺ too was tested by the death of his children."],["Anak perempuan dimuliakan dalam rumah tangga Baginda.","Daughters were honoured in his home."]],
 p:["khadijah","fatimah"],s:"His Marriage to Khadijah, p.37; The Prophet Household, p.311|Hidup penuh keperitan"},

{id:"s22",n:22,e:2,m:1,y:605,age:35,pl:"makkah",sc:"kaabah2",
 w:["Kira-kira 605","About 605"],
 t:["Kaabah dibina semula & Hajar Aswad","Rebuilding the Kaabah and the Black Stone"],
 f:["Ketika Rasulullah ﷺ berusia 35 tahun, banjir besar merosakkan dinding Kaabah. Quraisy memutuskan untuk membinanya semula dan hanya menggunakan harta yang halal, tanpa wang riba, pelacuran atau rompakan. Kerana harta halal tidak mencukupi, mereka memendekkan binaan di bahagian utara. Kawasan yang tertinggal itu kini dikenali sebagai Hijr Ismail.\nApabila sampai masa untuk meletakkan Hajar Aswad, setiap puak mahu mendapat penghormatan itu. Pertikaian berlarutan empat atau lima malam dan hampir membawa kepada pertumpahan darah. Abu Umayyah bin al-Mughirah mencadangkan agar orang pertama yang masuk melalui pintu masjid menjadi hakim. Orang itu ialah Muhammad ﷺ. Mereka berkata: “Ini al-Amin, kami reda.”\nBaginda membentangkan sehelai kain, meletakkan batu itu di tengahnya, dan meminta ketua setiap puak memegang hujung kain. Apabila diangkat ke tempatnya, Baginda sendiri meletakkan batu itu.",
   "When the Prophet ﷺ was 35, a great flood damaged the walls of the Kaabah. Quraysh decided to rebuild it using only lawful money, with nothing from usury, prostitution or robbery. As lawful money ran short, they left out a part on the north side. That area is now called Hijr Isma'il.\nWhen it was time to set the Black Stone in place, every clan wanted the honour. The dispute dragged on for four or five nights and almost led to bloodshed. Abu Umayyah ibn al-Mughirah proposed that the first person to enter through the masjid gate should judge. That person was Muhammad ﷺ. They said: “This is al-Amin. We accept him.”\nHe spread out a cloth, placed the stone in its middle, and asked the chief of each clan to hold its edge. When it was lifted to its place, he set the stone with his own hand."],
 k:["Kaabah rosak kerana banjir dan dibina semula. Semua puak mahu meletakkan batu Hajar Aswad dan mereka hampir bergaduh. Nabi ﷺ meletakkan batu itu di atas kain dan semua ketua mengangkatnya bersama-sama. Semua orang gembira!","The Kaabah was damaged by a flood and rebuilt. Every clan wanted to place the Black Stone, and they nearly fought. The Prophet ﷺ put the stone on a cloth and all the chiefs lifted it together. Everyone was happy!"],
 l:[["Kebijaksanaan boleh menyelesaikan pertelingkahan tanpa pertumpahan darah.","Wisdom can settle a dispute without bloodshed."],["Kepercayaan masyarakat dibina dengan akhlak bertahun-tahun.","People's trust is built by years of good character."]],
 s:"Rebuilding Al-Ka'bah and the Arbitration Issue, p.37|Pembinaan semula Kaabah dan permasalahan al-tahkim"},

{id:"s23",n:23,e:2,y:608,age:"37–40",pl:"hira",sc:"hira",
 w:["Kira-kira 608 hingga 610","About 608 to 610"],
 t:["Gemar beruzlah & mimpi yang benar","Love of solitude and true dreams"],
 f:["Semakin hampir usia empat puluh tahun, Rasulullah ﷺ semakin jauh daripada cara hidup kaumnya. Baginda suka bersendirian. Baginda membawa bekalan makanan dan air ke Gua Hira' di Jabal an-Nur, kira-kira dua batu dari Makkah. Gua itu kecil, panjangnya kira-kira empat hasta.\nBaginda menghabiskan bulan Ramadan di sana, beribadah dan memikirkan alam ciptaan Allah. Baginda juga memberi makan kepada orang miskin yang datang. Sebelum wahyu turun, Baginda mengalami mimpi-mimpi yang benar. Setiap mimpi menjadi kenyataan, jelas seperti cahaya subuh.",
   "As he neared forty, the Prophet ﷺ drew further away from the ways of his people. He loved solitude. He took food and water to the Cave of Hira' on Jabal an-Nur, about two miles from Makkah. The cave was small, about four cubits long.\nHe spent the month of Ramadan there, worshipping and reflecting on the creation of Allah, and he fed the poor who came by. Before revelation came, he began to see true dreams. Every dream came true, as clear as the light of dawn."],
 l:[["Masa bersendirian untuk berfikir dan beribadah menyuburkan jiwa.","Time alone to reflect and worship nourishes the soul."]],
 hd:[{r:"Sahih al-Bukhari 3",m:["Aisyah (r.a.) berkata: permulaan wahyu ialah mimpi yang benar. Setiap mimpi datang seperti cahaya subuh. Kemudian Baginda dijadikan suka bersendirian di Gua Hira'.","'A'ishah (r.a.) said: revelation began with true dreams, each one coming like the light of dawn. Then solitude was made dear to him, in the Cave of Hira'."]}],
 s:"A Rapid Review of Muhammad's Biography, p.37; In the Shade of the Message, p.44|Di Gua Hira"},

{id:"s24",n:24,e:3,m:1,y:610.6,age:40,pl:"hira",sc:"hira",
 w:["Malam Isnin, 21 Ramadan (10 Ogos 610)","Monday night, 21 Ramadan (10 August 610)"],
 t:["Wahyu pertama: Iqra'","The first revelation: Iqra'"],
 f:["Ketika Rasulullah ﷺ berada di Gua Hira', malaikat Jibril datang dan berkata: “Bacalah!” Baginda menjawab: “Aku tidak tahu membaca.” Jibril memeluknya dengan kuat hingga Baginda kepenatan, lalu melepaskannya dan mengulangi perintah itu. Ini berlaku tiga kali. Kemudian Jibril membaca lima ayat pertama Surah al-'Alaq.\nBaginda pulang kepada Khadijah dengan hati yang berdebar dan berkata: “Selimutkan aku, selimutkan aku.” Selepas rasa takutnya reda, Baginda menceritakan apa yang berlaku.\nMenurut Ar-Raheeq, peristiwa ini berlaku pada malam Isnin, 21 Ramadan, bersamaan 10 Ogos 610. Usia Baginda ketika itu tepat empat puluh tahun qamariah, enam bulan dan dua belas hari.",
   "While the Prophet ﷺ was in the Cave of Hira', the angel Jibril came and said: “Read!” He answered: “I am not a reader.” Jibril held him tightly until he was exhausted, then let go and repeated the command. This happened three times. Then Jibril recited the first five verses of Surah al-'Alaq.\nHe went home to Khadijah with his heart trembling, saying: “Cover me, cover me.” When his fear had passed, he told her what had happened.\nAccording to Ar-Raheeq, this was on Monday night, 21 Ramadan, which was 10 August 610. He was exactly forty lunar years, six months and twelve days old."],
 k:["Ketika Nabi ﷺ berada di Gua Hira', malaikat Jibril datang dan berkata: “Bacalah!” Itulah ayat pertama al-Quran. Pada usia 40 tahun, Muhammad ﷺ menjadi Rasul Allah.","While the Prophet ﷺ was in the Cave of Hira', the angel Jibril came and said: “Read!” These were the first verses of the Quran. At 40 years old, Muhammad ﷺ became the Messenger of Allah."],
 l:[["Wahyu pertama ialah perintah membaca: ilmu ialah asas Islam.","The first revelation was a command to read: knowledge is the base of Islam."],["Perasaan takut ketika menghadapi perkara besar ialah fitrah manusia.","Feeling afraid before something tremendous is human."]],
 ay:[{kid:1,r:"al-'Alaq 96:1-5",ar:"اقْرَأْ بِاسْمِ رَبِّكَ الَّذِي خَلَقَ ۝ خَلَقَ الْإِنسَانَ مِنْ عَلَقٍ ۝ اقْرَأْ وَرَبُّكَ الْأَكْرَمُ ۝ الَّذِي عَلَّمَ بِالْقَلَمِ ۝ عَلَّمَ الْإِنسَانَ مَا لَمْ يَعْلَمْ",m:["Bacalah dengan nama Tuhanmu yang menciptakan. Dia menciptakan manusia daripada segumpal darah. Bacalah, dan Tuhanmu Maha Pemurah, yang mengajar dengan pena, mengajar manusia apa yang tidak diketahuinya.","Read in the name of your Lord who created. He created man from a clinging clot. Read, and your Lord is the Most Generous, who taught by the pen, taught man what he did not know."]}],
 hd:[{r:"Sahih al-Bukhari 3",m:["Aisyah (r.a.) meriwayatkan kisah penuh wahyu pertama di Gua Hira' dan kepulangan Baginda kepada Khadijah.","'A'ishah (r.a.) narrated the full story of the first revelation at Hira' and his return to Khadijah."]}],
 o:["Di Malaysia, Nuzul al-Quran disambut pada 17 Ramadan berdasarkan pendapat lain.","In Malaysia, Nuzul al-Quran is marked on 17 Ramadan, following another view."],
 p:["khadijah"],s:"In the Cave of Hira', p.44|Di Gua Hira"},

{id:"s25",n:25,e:3,y:610.62,age:40,pl:"makkah",sc:"book",
 w:["Ramadan 610, selepas wahyu pertama","Ramadan 610, after the first revelation"],
 t:["Khadijah & Waraqah bin Naufal","Khadijah and Waraqah ibn Nawfal"],
 f:["Khadijah menenangkan suaminya dengan kata-kata yang indah: “Demi Allah, Allah tidak akan menghinamu selama-lamanya. Engkau menyambung silaturahim, membantu orang yang lemah, memberi kepada orang yang tiada, memuliakan tetamu dan menolong orang dalam kesusahan.”\nKemudian beliau membawa Baginda kepada sepupunya, Waraqah bin Naufal, seorang tua yang buta dan arif tentang kitab Injil. Selepas mendengar cerita Baginda, Waraqah berkata: “Itulah Namus (Jibril) yang pernah diutus kepada Musa. Alangkah baiknya jika aku masih muda ketika kaummu mengusirmu.” Baginda bertanya: “Adakah mereka akan mengusirku?” Waraqah menjawab: “Ya. Tiada seorang pun yang membawa seperti yang engkau bawa melainkan dia dimusuhi.” Tidak lama kemudian Waraqah meninggal dunia.",
   "Khadijah comforted her husband with beautiful words: “By Allah, Allah will never disgrace you. You keep the ties of kinship, carry the weak, give to the destitute, honour guests and help people in hardship.”\nThen she took him to her cousin Waraqah ibn Nawfal, an old blind man learned in the Gospel. On hearing the story, Waraqah said: “That is the Namus (Jibril) who was sent to Musa. I wish I were young when your people drive you out.” He asked: “Will they drive me out?” Waraqah said: “Yes. No one has ever brought what you bring without being treated as an enemy.” Waraqah died soon after."],
 l:[["Pasangan yang baik menenangkan dan menyokong ketika saat sukar.","A good spouse comforts and supports in hard moments."],["Akhlak mulia ialah tanda perlindungan Allah.","Good character is a sign of Allah's protection."]],
 hd:[{r:"Sahih al-Bukhari 3",m:["Kata-kata Khadijah dan jawapan Waraqah diriwayatkan dalam hadith permulaan wahyu.","Khadijah's words and Waraqah's reply are narrated in the hadith of the beginning of revelation."]}],
 p:["khadijah","waraqah"],s:"In the Cave of Hira', p.44|Di Gua Hira"},

{id:"s26",n:26,e:3,y:610.65,age:40,pl:"makkah",sc:"hira",
 w:["610, beberapa hari","610, a few days"],
 t:["Wahyu terhenti seketika","The pause in revelation"],
 f:["Selepas wahyu pertama, wahyu terhenti buat seketika. Menurut riwayat Ibn Sa'd daripada Ibn 'Abbas, tempohnya hanya beberapa hari, dan pendapat inilah yang dipilih dalam Ar-Raheeq selepas kajian.\nDalam tempoh itu Rasulullah ﷺ sangat bersedih dan kehairanan. Baginda sering naik ke puncak bukit, dan setiap kali itu Jibril menampakkan diri lalu berkata: “Wahai Muhammad, sesungguhnya engkau benar-benar utusan Allah.” Hati Baginda pun kembali tenang.\nPenangguhan ini menghilangkan rasa gerun dan menumbuhkan rasa rindu kepada wahyu, sebagai persiapan untuk tugas yang besar.",
   "After the first revelation, revelation paused for a while. According to Ibn Sa'd from Ibn 'Abbas it lasted only a few days, and Ar-Raheeq chooses this view after study.\nDuring that time the Prophet ﷺ was very sad and bewildered. He often went up to the mountain tops, and each time Jibril appeared and said: “O Muhammad, you are truly the Messenger of Allah.” Then his heart would be calm again.\nThe pause took away his awe and planted a longing for revelation, preparing him for the great task ahead."],
 l:[["Allah mendidik Rasul-Nya secara beransur-ansur.","Allah prepared His Messenger step by step."]],
 o:["Ada pendapat yang mengatakan penangguhan itu berlanjutan dua tahun setengah atau tiga tahun. Ar-Raheeq menolak pendapat ini.","Some say the pause lasted two and a half or three years. Ar-Raheeq rejects this view."],
 s:"Interruption of Revelation, p.44|Penangguhan wahyu"},

{id:"s27",n:27,e:3,y:610.7,age:40,pl:"makkah",sc:"hira",
 w:["610","610"],
 t:["Wahyu kembali: al-Muddaththir","Revelation returns: al-Muddaththir"],
 f:["Rasulullah ﷺ menceritakan: ketika Baginda sedang berjalan, Baginda terdengar suara dari langit. Apabila mendongak, Baginda melihat malaikat yang datang di Gua Hira' sedang duduk di atas kerusi di antara langit dan bumi. Baginda gementar, pulang dan berkata: “Selimutkan aku.”\nLalu Allah menurunkan permulaan Surah al-Muddaththir: “Wahai orang yang berselimut, bangunlah dan berilah peringatan.” Dengan ayat-ayat ini, Baginda bukan sahaja seorang nabi tetapi juga seorang rasul yang diperintah menyeru manusia. Selepas itu wahyu turun berterusan.",
   "The Prophet ﷺ related: as he was walking, he heard a voice from the sky. Looking up, he saw the angel who had come at Hira' sitting on a chair between the sky and the earth. He trembled, went home and said: “Cover me.”\nThen Allah revealed the opening of Surah al-Muddaththir: “O you wrapped in your cloak, arise and warn.” With these verses he was not only a prophet but a messenger commanded to call people. After this, revelation came steadily."],
 l:[["Selepas menerima ilmu, datang tugas menyampaikan.","After receiving knowledge comes the duty to pass it on."]],
 ay:[{r:"al-Muddaththir 74:1-2",ar:"يَا أَيُّهَا الْمُدَّثِّرُ ۝ قُمْ فَأَنذِرْ",m:["Wahai orang yang berselimut, bangunlah, lalu berilah peringatan.","O you wrapped in your cloak, arise and warn."]}],
 hd:[{r:"Sahih al-Bukhari 4",m:["Jabir bin Abdullah (r.a.) meriwayatkan cerita Baginda melihat malaikat di antara langit dan bumi.","Jabir ibn 'Abdullah (r.a.) narrated how the Prophet saw the angel between the sky and the earth."]}],
 s:"Once More, Gabriel Brings Allah's Revelation, p.44|Jibril membawa wahyu di kali kedua"},

{id:"s28",n:28,e:3,m:1,y:611,age:"40–43",pl:"makkah",sc:"birth",
 w:["610 hingga 613","610 to 613"],
 t:["Generasi pertama yang beriman","The first believers"],
 f:["Rasulullah ﷺ mula menyeru orang yang paling dekat dengannya. Orang pertama yang beriman ialah isterinya Khadijah (r.a.). Kemudian Zaid bin Harithah, hamba yang dimerdekakan dan dikasihi Baginda, dan sepupunya Ali bin Abi Talib, yang ketika itu masih kanak-kanak dan tinggal di rumah Baginda. Sahabat karibnya, Abu Bakar, ialah lelaki dewasa merdeka yang pertama beriman.\nAbu Bakar seorang peniaga yang disenangi ramai. Melalui dakwahnya, beberapa tokoh memeluk Islam: Uthman bin Affan, az-Zubair bin al-Awwam, Abdul Rahman bin Auf, Sa'd bin Abi Waqqas dan Talhah bin Ubaidillah. Kemudian datang Bilal, Abu Ubaidah, Abu Salamah, al-Arqam dan ramai lagi. Mereka digelar as-Sabiqun al-Awwalun, golongan yang terawal.",
   "The Prophet ﷺ began by calling those closest to him. The first to believe was his wife Khadijah (r.a.). Then came Zayd ibn Harithah, the freed slave he loved, and his cousin 'Ali ibn Abi Talib, still a child living in his home. His close friend Abu Bakr was the first free grown man to believe.\nAbu Bakr was a well-liked merchant. Through his call, several leading men accepted Islam: 'Uthman ibn 'Affan, az-Zubayr ibn al-'Awwam, 'Abdur-Rahman ibn 'Awf, Sa'd ibn Abi Waqqas and Talhah ibn 'Ubaydullah. Then came Bilal, Abu 'Ubaydah, Abu Salamah, al-Arqam and many more. They are called as-Sabiqun al-Awwalun, the foremost."],
 k:["Orang pertama yang beriman kepada Nabi ﷺ ialah isterinya, Khadijah. Kemudian Abu Bakar, sahabat baiknya, Ali yang masih kecil, dan Zaid. Merekalah sahabat-sahabat yang terawal.","The first person to believe in the Prophet ﷺ was his wife Khadijah. Then came Abu Bakr, his best friend, young 'Ali, and Zayd. They were the very first companions."],
 l:[["Dakwah bermula dengan keluarga dan sahabat terdekat.","The call begins with family and close friends."],["Seorang sahabat yang baik boleh membawa ramai orang kepada kebaikan.","One good friend can bring many people to good."]],
 p:["khadijah","abubakar","ali","zaid","uthman","bilal","arqam"],s:"The Early Converts, p.48|Generasi pertama"},

{id:"s29",n:29,e:3,y:612,age:"40–43",pl:"makkah",sc:"valley",
 w:["610 hingga 613","610 to 613"],
 t:["Tiga tahun dakwah rahsia & solat awal","Three years of secret call and the early prayer"],
 f:["Selama kira-kira tiga tahun, dakwah dijalankan secara rahsia. Rasulullah ﷺ hanya menyeru orang yang dipercayai, dan orang Islam menyembunyikan iman mereka.\nSolat difardukan sejak awal, sebelum solat lima waktu. Menurut riwayat yang disebut dalam Ar-Raheeq, mereka bersolat dua rakaat pada waktu pagi dan dua rakaat pada waktu petang. Para sahabat pergi ke lorong-lorong bukit di luar Makkah untuk bersolat supaya tidak dilihat oleh kaum mereka.\nPada akhir tempoh ini, jumlah orang Islam sudah melebihi empat puluh orang, lelaki dan wanita, kebanyakannya muda.",
   "For about three years the call was made in secret. The Prophet ﷺ invited only people he trusted, and the Muslims kept their faith hidden.\nPrayer was ordained from the start, before the five daily prayers. According to a report cited in Ar-Raheeq, they prayed two rak'ahs in the morning and two in the evening. The companions went into the mountain passes outside Makkah to pray, so their people would not see them.\nBy the end of this period the Muslims numbered more than forty, men and women, most of them young."],
 l:[["Strategi dan kebijaksanaan penting pada permulaan sesuatu usaha.","Strategy and wisdom matter at the start of any effort."],["Solat ialah amalan utama sejak hari pertama.","Prayer was the central act from the very first days."]],
 s:"Three Years of Secret Call; As-Salat, p.48|Tahap pertama: jihad melalui dakwah"},

{id:"s30",n:30,e:4,y:613,age:43,pl:"makkah",sc:"birth",
 w:["Tahun ke-4 kenabian (613)","Year 4 of prophethood (613)"],
 t:["Seruan kepada keluarga terdekat","Calling the closest kin"],
 f:["Allah memerintahkan: “Dan berilah peringatan kepada kaum kerabatmu yang terdekat.” Rasulullah ﷺ menjemput Bani Hasyim dan Bani Muttalib, kira-kira empat puluh lima orang, untuk makan. Abu Lahab bercakap dahulu dengan kasar, dan majlis itu bersurai.\nBaginda menjemput mereka sekali lagi dan berkata: “Aku ialah Rasul Allah kepada kamu khususnya dan kepada seluruh manusia.” Abu Talib berkata: “Kami akan membantumu dan melindungimu, walaupun aku tidak dapat meninggalkan agama Abdul Muttalib.” Abu Lahab pula mendesak agar Baginda dihalang sebelum orang lain bertindak. Abu Talib menjawab: “Demi Allah, kami akan melindunginya selagi kami hidup.”",
   "Allah commanded: “And warn your nearest kin.” The Prophet ﷺ invited Banu Hashim and Banu al-Muttalib, about forty-five men, to a meal. Abu Lahab spoke first, rudely, and the gathering broke up.\nHe invited them a second time and said: “I am the Messenger of Allah to you in particular and to all people.” Abu Talib said: “We will help you and protect you, though I cannot leave the religion of 'Abdul-Muttalib.” Abu Lahab urged them to stop him before others did. Abu Talib replied: “By Allah, we will protect him as long as we live.”"],
 l:[["Keluarga ialah tanggungjawab pertama dalam dakwah.","Family is the first responsibility in calling to good."],["Tidak semua yang melindungi kita berkongsi iman kita.","Not everyone who protects us shares our faith."]],
 ay:[{r:"asy-Syu'ara' 26:214",ar:"وَأَنذِرْ عَشِيرَتَكَ الْأَقْرَبِينَ",m:["Dan berilah peringatan kepada kaum kerabatmu yang terdekat.","And warn your nearest kin."]}],
 p:["abutalib","abulahab"],s:"Calling the Closest Kinspeople, p.52|Seruan kepada keluarga terdekat"},

{id:"s31",n:31,e:4,m:1,y:613.2,age:43,pl:"makkah",sc:"safa",
 w:["Tahun ke-4 kenabian (613)","Year 4 of prophethood (613)"],
 t:["Seruan di Bukit Safa","The call from Mount Safa"],
 f:["Rasulullah ﷺ naik ke atas Bukit Safa dan memanggil: “Ya Sabahah!”, seruan tanda bahaya. Puak-puak Quraisy pun berkumpul. Baginda bertanya: “Jika aku katakan ada pasukan berkuda di sebalik bukit ini yang akan menyerang kamu, adakah kamu percaya?” Mereka menjawab: “Ya, kami tidak pernah mendapati engkau berdusta.”\nBaginda bersabda: “Sesungguhnya aku memberi peringatan kepada kamu tentang azab yang berat.” Abu Lahab menjawab: “Celakalah engkau sepanjang hari ini! Adakah untuk ini engkau mengumpulkan kami?” Lalu Allah menurunkan Surah al-Masad.\nInilah permulaan dakwah secara terang-terangan di Makkah.",
   "The Prophet ﷺ climbed Mount Safa and called out: “Ya Sabahah!”, the cry of alarm. The clans of Quraysh gathered. He asked: “If I told you that horsemen behind this hill were about to attack you, would you believe me?” They said: “Yes, we have never known you to lie.”\nHe said: “Then I am warning you of a severe punishment.” Abu Lahab replied: “May you perish all day! Is this why you gathered us?” Then Allah revealed Surah al-Masad.\nThis was the start of the open call in Makkah."],
 k:["Nabi ﷺ naik ke atas Bukit Safa dan memanggil semua orang. Baginda bertanya: “Adakah kamu percaya kepadaku?” Mereka berkata: “Ya, kamu tidak pernah berbohong!” Lalu Baginda mengajak mereka menyembah Allah sahaja.","The Prophet ﷺ climbed Mount Safa and called everyone together. He asked: “Do you trust me?” They said: “Yes, you have never lied!” Then he called them to worship Allah alone."],
 l:[["Rekod kejujuran ialah modal terbesar seorang pendakwah.","A record of honesty is a caller's greatest asset."],["Kebenaran disampaikan walaupun ditentang oleh keluarga sendiri.","The truth is told even when one's own family opposes it."]],
 ay:[{r:"al-Masad 111:1",ar:"تَبَّتْ يَدَا أَبِي لَهَبٍ وَتَبَّ",m:["Binasalah kedua-dua tangan Abu Lahab, dan binasalah dia.","May the hands of Abu Lahab perish, and may he perish."]}],
 hd:[{r:"Sahih al-Bukhari 4770",m:["Ibn 'Abbas (r.a.) meriwayatkan seruan Baginda di Safa dan jawapan Abu Lahab.","Ibn 'Abbas (r.a.) narrated the call at Safa and Abu Lahab's reply."]}],
 p:["abulahab"],s:"On Mount As-Safa, p.52|Di Bukit al-Safa"},

{id:"s32",n:32,e:4,y:613.6,age:43,pl:"makkah",sc:"market",
 w:["Menjelang musim haji, tahun ke-4","Before the Hajj season, year 4"],
 t:["Quraisy mahu menghalang jemaah haji","Quraysh plan to turn pilgrims away"],
 f:["Menjelang musim haji, Quraisy bimbang dakwah Rasulullah ﷺ akan didengar oleh jemaah dari seluruh Arab. Mereka berkumpul di rumah al-Walid bin al-Mughirah untuk bersepakat tentang tuduhan yang sama. Mereka mencadangkan tukang tilik, orang gila, penyair dan ahli sihir. Al-Walid menolak semuanya kerana al-Quran tidak menyerupai satu pun daripadanya.\nAkhirnya mereka memilih tuduhan ‘ahli sihir yang memisahkan seseorang daripada ayah, saudara, isteri dan kaumnya’. Mereka berdiri di jalan-jalan jemaah untuk memberi amaran, dan Abu Lahab mengekori Baginda sambil berkata bahawa Baginda pendusta. Namun usaha ini berbalik: nama Rasulullah ﷺ tersebar ke seluruh semenanjung Arab.",
   "As the Hajj season drew near, Quraysh feared the Prophet's ﷺ call would reach pilgrims from all over Arabia. They met at the house of al-Walid ibn al-Mughirah to agree on one accusation. They suggested soothsayer, madman, poet and sorcerer. Al-Walid rejected all of them, because the Quran resembled none of these.\nIn the end they chose ‘a sorcerer who separates a man from his father, brother, wife and clan’. They stood on the pilgrims' roads to warn them, and Abu Lahab followed the Prophet ﷺ calling him a liar. But the plan backfired: the Prophet's ﷺ name spread across the whole of Arabia."],
 l:[["Usaha menghalang kebenaran sering menjadi sebab ia tersebar.","Efforts to block the truth often spread it further."]],
 ay:[{r:"al-Muddaththir 74:18-19",ar:"إِنَّهُ فَكَّرَ وَقَدَّرَ ۝ فَقُتِلَ كَيْفَ قَدَّرَ",m:["Sesungguhnya dia telah berfikir dan menetapkan. Maka binasalah dia, bagaimana dia menetapkan?","Indeed he thought and deliberated. So may he be destroyed, how he deliberated!"]}],
 p:["abulahab"],s:"An Advisory Council to Debar Pilgrims, p.52|Majlis permesyuaratan bersidang untuk mencegah jemaah haji"},

{id:"s33",n:33,e:4,y:614,age:"43–46",pl:"makkah",sc:"kaabah",
 w:["Tahun ke-4 hingga ke-6 kenabian","Years 4 to 6 of prophethood"],
 t:["Ejekan & usaha menyekat dakwah","Mockery and other attempts to stop Islam"],
 f:["Quraisy mencuba pelbagai cara untuk memadamkan dakwah. Mereka mengejek dan mempersenda Rasulullah ﷺ, menuduhnya gila dan pendusta. An-Nadr bin al-Harith menceritakan kisah raja-raja Parsi untuk mengalih perhatian orang daripada al-Quran. Mereka meminta mukjizat yang pelik sebagai syarat untuk beriman.\nMereka juga cuba berkompromi: mereka akan menyembah Allah selama setahun jika Baginda menyembah tuhan-tuhan mereka setahun. Lalu turun Surah al-Kafirun yang menolak tawaran itu dengan tegas. Dalam semua ini, Baginda tetap sabar dan terus berdakwah.",
   "Quraysh tried many ways to put out the call. They mocked and ridiculed the Prophet ﷺ, calling him mad and a liar. An-Nadr ibn al-Harith told tales of the Persian kings to pull people away from the Quran. They demanded strange miracles as a condition for belief.\nThey also tried a compromise: they would worship Allah for a year if he worshipped their gods for a year. Then Surah al-Kafirun was revealed, firmly refusing the offer. Through all this he stayed patient and kept calling."],
 l:[["Akidah tidak boleh ditawar-menawar.","Belief is not up for bargaining."],["Kesabaran menghadapi ejekan ialah sunnah para nabi.","Patience with mockery is the way of the prophets."]],
 ay:[{r:"al-Kafirun 109:1-2",ar:"قُلْ يَا أَيُّهَا الْكَافِرُونَ ۝ لَا أَعْبُدُ مَا تَعْبُدُونَ",m:["Katakanlah: Wahai orang-orang kafir, aku tidak menyembah apa yang kamu sembah.","Say: O disbelievers, I do not worship what you worship."]}],
 s:"Attempts Made to Check the Onward March of Islam, p.52|Pelbagai cara menentang dakwah Rasulullah"},

{id:"s34",n:34,e:4,m:1,y:614.5,age:"44–46",pl:"makkah",sc:"sunset",
 w:["Dari akhir tahun ke-4 kenabian","From late year 4 of prophethood"],
 t:["Penyeksaan: Bilal, keluarga Yasir, Khabbab","Persecution: Bilal, the family of Yasir, Khabbab"],
 f:["Apabila ejekan tidak berhasil, Quraisy beralih kepada penyeksaan, terutama terhadap orang Islam yang lemah dan tiada pelindung.\nBilal bin Rabah dibaringkan di atas pasir panas oleh tuannya Umayyah bin Khalaf, dengan batu besar di atas dadanya, tetapi beliau terus menyebut: “Ahad, Ahad.” Abu Bakar membelinya dan memerdekakannya. Keluarga Yasir dari Bani Makhzum diseksa di bawah terik matahari. Rasulullah ﷺ melalui mereka dan berkata: “Bersabarlah, wahai keluarga Yasir, tempat yang dijanjikan untuk kamu ialah syurga.” Sumayyah dibunuh oleh Abu Jahal, menjadi syahid pertama dalam Islam, dan Yasir juga meninggal kerana penyeksaan. Khabbab bin al-Aratt diseksa dengan bara api.\nRasulullah ﷺ sendiri disakiti: ketika Baginda sujud di Kaabah, Uqbah bin Abi Mu'ait meletakkan isi perut unta di atas belakangnya.",
   "When mockery failed, Quraysh turned to torture, above all of Muslims who were weak and had no protector.\nBilal ibn Rabah was laid on the burning sand by his master Umayyah ibn Khalaf, with a heavy rock on his chest, yet he kept saying: “Ahad, Ahad (One, One).” Abu Bakr bought him and set him free. The family of Yasir of Banu Makhzum were tortured under the blazing sun. The Prophet ﷺ passed by and said: “Be patient, O family of Yasir; your promised place is Paradise.” Sumayyah was killed by Abu Jahl, the first martyr of Islam, and Yasir also died from the torture. Khabbab ibn al-Aratt was tortured with hot coals.\nThe Prophet ﷺ himself was harmed: while he prostrated at the Kaabah, 'Uqbah ibn Abi Mu'ayt put a camel's entrails on his back."],
 k:["Sesetengah orang Islam disakiti kerana iman mereka. Bilal dibiarkan di bawah panas matahari dengan batu berat di atas badannya, tetapi beliau terus berkata: “Ahad, Ahad”, Allah Maha Esa. Abu Bakar membeli Bilal dan membebaskannya.","Some Muslims were hurt because of their faith. Bilal was left in the hot sun with a heavy rock on him, but he kept saying: “Ahad, Ahad”, Allah is One. Abu Bakr bought Bilal and set him free."],
 l:[["Iman yang kukuh tidak dapat dipatahkan oleh penyeksaan.","Firm faith cannot be broken by torture."],["Membebaskan orang yang tertindas ialah amal yang besar.","Freeing the oppressed is a great deed."]],
 ay:[{r:"an-Nahl 16:106",ar:"إِلَّا مَنْ أُكْرِهَ وَقَلْبُهُ مُطْمَئِنٌّ بِالْإِيمَانِ",m:["Kecuali orang yang dipaksa sedangkan hatinya tetap tenang dengan iman.","Except one who is forced while his heart is at rest in faith."]}],
 o:["Ayat ini turun tentang Ammar bin Yasir yang dipaksa menyebut kata-kata kufur ketika diseksa.","This verse was revealed about 'Ammar ibn Yasir, who was forced to say words of disbelief under torture."],
 p:["bilal","yasir","abubakar","abujahal"],s:"Persecutions, p.52|Penyiksaan"},

{id:"s35",n:35,e:4,y:615,age:45,pl:"makkah",sc:"arqam",
 w:["Tahun ke-5 kenabian","Year 5 of prophethood"],
 t:["Dar al-Arqam","The House of al-Arqam"],
 f:["Untuk melindungi orang Islam, Rasulullah ﷺ menjadikan rumah al-Arqam bin Abi al-Arqam di kaki Bukit Safa sebagai tempat berkumpul secara rahsia, jauh daripada pandangan musuh.\nDi sinilah Baginda membacakan al-Quran, mengajar dan mendidik para sahabat. Rumah ini menjadi madrasah pertama Islam, tempat lahirnya generasi yang kemudiannya membawa Islam ke seluruh dunia. Ramai yang memeluk Islam di rumah ini, termasuk Umar al-Khattab.",
   "To protect the Muslims, the Prophet ﷺ made the house of al-Arqam ibn Abi al-Arqam, at the foot of Safa, their secret meeting place, away from enemy eyes.\nHere he recited the Quran, taught and trained his companions. The house became the first school of Islam, where the generation that would carry Islam to the world was formed. Many accepted Islam in this house, including 'Umar ibn al-Khattab."],
 l:[["Pendidikan yang tersusun membina generasi yang kuat.","Organised learning builds a strong generation."],["Kebijaksanaan menjaga keselamatan adalah sebahagian daripada dakwah.","Wisely guarding safety is part of the call."]],
 p:["arqam"],s:"The House of Al-Arqum, p.52|"},

{id:"s36",n:36,e:4,m:1,y:615.3,age:45,pl:"habsyah",sc:"ship",
 w:["Rejab, tahun ke-5 kenabian (615)","Rajab, year 5 of prophethood (615)"],
 t:["Hijrah pertama ke Habsyah","The first migration to Abyssinia"],
 f:["Apabila penyeksaan semakin berat, Rasulullah ﷺ mengizinkan sebahagian sahabat berhijrah ke Habsyah. Raja negeri itu, an-Najasyi, terkenal adil dan tiada sesiapa dizalimi di bawah pemerintahannya.\nPada bulan Rejab tahun kelima kenabian, dua belas lelaki dan empat wanita keluar secara senyap pada waktu malam. Mereka diketuai oleh Uthman bin Affan bersama isterinya Ruqayyah, puteri Rasulullah ﷺ. Mereka sampai ke pelabuhan Syu'aibah dan menaiki dua buah kapal dagang. Quraisy mengejar mereka hingga ke pantai, tetapi kapal-kapal itu sudah belayar.\nKemudian, satu rombongan yang lebih besar menyusul, iaitu lebih lapan puluh lelaki dan hampir dua puluh wanita.",
   "As the torture grew worse, the Prophet ﷺ allowed some companions to migrate to Abyssinia. Its king, the Negus, was known for justice, and no one was wronged under his rule.\nIn Rajab of the fifth year of prophethood, twelve men and four women slipped away at night. They were led by 'Uthman ibn 'Affan with his wife Ruqayyah, the Prophet's ﷺ daughter. They reached the port of Shu'aybah and boarded two trading ships. Quraysh chased them to the shore, but the ships had already sailed.\nLater a larger group followed: more than eighty men and nearly twenty women."],
 k:["Kerana orang Islam disakiti di Makkah, Nabi ﷺ membenarkan sebahagian mereka menaiki kapal ke Habsyah. Di sana ada seorang raja yang adil bernama Najasyi. Mereka dapat menyembah Allah dengan aman.","Because the Muslims were being hurt in Makkah, the Prophet ﷺ let some of them sail to Abyssinia. A fair king called the Negus ruled there. They could worship Allah in peace."],
 l:[["Berpindah untuk menjaga agama ialah satu bentuk perjuangan.","Moving to protect one's faith is a kind of striving."],["Keadilan dihargai Islam walaupun daripada pemimpin bukan Islam.","Islam values justice even from a non-Muslim ruler."]],
 p:["uthman","najasyi","jafar"],s:"The First Migration to Abyssinia, p.52|"},

{id:"s37",n:37,e:4,y:615.5,age:45,pl:"makkah",sc:"kaabah",
 w:["Ramadan, tahun ke-5 kenabian","Ramadan, year 5 of prophethood"],
 t:["Sujud bersama selepas Surah an-Najm","The prostration after Surah an-Najm"],
 f:["Pada bulan Ramadan tahun yang sama, Rasulullah ﷺ membaca Surah an-Najm di Masjidil Haram di hadapan orang ramai, termasuk pembesar Quraisy. Mereka belum pernah mendengar al-Quran dibaca sepenuhnya di hadapan mereka. Keindahan dan kekuatan ayat-ayat itu menguasai mereka.\nApabila Baginda sampai ke ayat terakhir, “Maka sujudlah kepada Allah dan sembahlah Dia”, Baginda sujud. Semua yang hadir sujud bersama, orang Islam dan musyrikin, kecuali seorang lelaki tua yang hanya mengambil segenggam tanah dan meletakkannya ke dahinya.\nBerita ini sampai ke Habsyah dalam bentuk yang salah, seolah-olah Quraisy telah memeluk Islam. Sebahagian muhajirin pun pulang pada bulan Syawal, lalu mendapati keadaan masih sama.",
   "In Ramadan of the same year, the Prophet ﷺ recited Surah an-Najm at the Sacred Masjid before a crowd that included the leaders of Quraysh. They had never heard the Quran recited in full in front of them. The beauty and force of the verses overwhelmed them.\nWhen he reached the last verse, “So prostrate to Allah and worship Him”, he prostrated. Everyone present prostrated with him, believers and idolaters, except one old man who only picked up a handful of earth and pressed it to his forehead.\nThe news reached Abyssinia in a distorted form, as if Quraysh had accepted Islam. Some emigrants came home in Shawwal, only to find nothing had changed."],
 l:[["Al-Quran mempunyai kekuatan yang menyentuh hati, malah hati yang menentang.","The Quran has a power that touches hearts, even hostile ones."],["Semak sesuatu berita sebelum bertindak.","Check news before acting on it."]],
 ay:[{r:"an-Najm 53:62",ar:"فَاسْجُدُوا لِلَّهِ وَاعْبُدُوا",m:["Maka sujudlah kepada Allah dan sembahlah Dia.","So prostrate to Allah and worship Him."]}],
 hd:[{r:"Sahih al-Bukhari 1067",m:["Ibn Mas'ud (r.a.) menceritakan Baginda membaca an-Najm lalu sujud, dan semua yang bersamanya sujud kecuali seorang lelaki tua.","Ibn Mas'ud (r.a.) related that he recited an-Najm and prostrated, and all with him prostrated except one old man."]}],
 s:"The First Migration to Abyssinia, p.52|"},

{id:"s38",n:38,e:4,y:616,age:46,pl:"habsyah",sc:"court",
 w:["Tahun ke-5 atau ke-6 kenabian","Year 5 or 6 of prophethood"],
 t:["Ja'far di hadapan an-Najasyi","Ja'far before the Negus"],
 f:["Quraisy menghantar Amr bin al-'As dan Abdullah bin Abi Rabi'ah membawa hadiah kepada an-Najasyi dan paderi-paderinya, meminta para muhajirin diserahkan semula. An-Najasyi enggan memutuskan sebelum mendengar penjelasan orang Islam.\nJa'far bin Abi Talib berucap: “Wahai raja, dahulu kami kaum jahil yang menyembah berhala, memakan bangkai, memutuskan silaturahim dan menzalimi jiran. Lalu Allah mengutus seorang rasul yang kami kenali keturunan, kejujuran dan amanahnya.” Beliau membaca permulaan Surah Maryam. An-Najasyi menangis hingga basah janggutnya, lalu berkata bahawa ajaran ini dan ajaran Isa datang dari sumber cahaya yang sama.\nKeesokan harinya, Amr cuba lagi dengan bertanya pandangan mereka tentang Isa. Ja'far menjawab bahawa Isa ialah hamba Allah, rasul-Nya, roh dan kalimah-Nya yang disampaikan kepada Maryam. An-Najasyi bersetuju, memulangkan hadiah Quraisy dan melindungi orang Islam.",
   "Quraysh sent 'Amr ibn al-'As and 'Abdullah ibn Abi Rabi'ah with gifts to the Negus and his bishops, asking for the emigrants to be handed back. The Negus would not decide before hearing the Muslims.\nJa'far ibn Abi Talib spoke: “O king, we were an ignorant people, worshipping idols, eating carrion, cutting family ties and wronging our neighbours. Then Allah sent us a messenger whose lineage, truthfulness and honesty we knew.” He recited the opening of Surah Maryam. The Negus wept until his beard was wet, and said that this and what 'Isa brought came from the same source of light.\nThe next day 'Amr tried again by asking what they said about 'Isa. Ja'far answered that 'Isa is the servant of Allah, His messenger, His spirit and His word given to Maryam. The Negus agreed, returned the gifts of Quraysh and protected the Muslims."],
 l:[["Kebenaran yang disampaikan dengan jujur dan tenang mampu melembutkan hati.","Truth told honestly and calmly can soften hearts."],["Islam menghormati para nabi terdahulu.","Islam honours the earlier prophets."]],
 ay:[{r:"Maryam 19:16",ar:"وَاذْكُرْ فِي الْكِتَابِ مَرْيَمَ",m:["Dan ceritakanlah (wahai Muhammad) di dalam Kitab (al-Quran) tentang Maryam.","And mention in the Book (the story of) Maryam."]}],
 p:["jafar","najasyi"],s:"Quraish's Machination Against the Emigrants, p.52|"},

{id:"s39",n:39,e:4,y:616.4,age:46,pl:"makkah",sc:"birth",
 w:["Tahun ke-6 kenabian","Year 6 of prophethood"],
 t:["Quraisy mendesak Abu Talib","Quraysh press Abu Talib again"],
 f:["Pembesar Quraisy datang lagi kepada Abu Talib dengan ancaman: “Hentikan anak saudaramu, atau kami akan memerangi kamu berdua sehingga salah satu pihak binasa.” Abu Talib berasa berat, lalu memanggil Rasulullah ﷺ dan memintanya mengasihani dirinya dan bapa saudaranya.\nBaginda menjawab: “Wahai bapa saudaraku, demi Allah, sekiranya mereka meletakkan matahari di tangan kananku dan bulan di tangan kiriku supaya aku meninggalkan urusan ini, aku tidak akan meninggalkannya sehingga Allah memenangkannya atau aku binasa kerananya.” Abu Talib tersentuh dan berkata: “Pergilah, wahai anak saudaraku, katakanlah apa yang engkau suka. Demi Allah, aku tidak akan menyerahkanmu.”",
   "The leaders of Quraysh came to Abu Talib again with a threat: “Stop your nephew, or we will fight you both until one side perishes.” Abu Talib felt the weight of it, called the Prophet ﷺ and asked him to spare himself and his uncle.\nHe replied: “O my uncle, by Allah, if they put the sun in my right hand and the moon in my left so that I would give up this matter, I would not give it up until Allah makes it prevail or I perish for it.” Abu Talib was moved and said: “Go, my nephew, and say what you like. By Allah, I will never hand you over.”"],
 l:[["Keteguhan pendirian lahir daripada keyakinan kepada Allah.","Steadfastness comes from certainty in Allah."]],
 p:["abutalib"],s:"Once More Quraish Approaches Abu Talib, p.52|"},

{id:"s40",n:40,e:4,m:1,y:616.95,age:46,pl:"makkah",sc:"safa",
 w:["Zulhijjah, tahun ke-6 kenabian (616)","Dhul-Hijjah, year 6 of prophethood (616)"],
 t:["Hamzah memeluk Islam","Hamzah accepts Islam"],
 f:["Suatu hari Abu Jahal menghina dan menyakiti Rasulullah ﷺ berhampiran Bukit Safa. Baginda tidak membalas. Seorang hamba perempuan Abdullah bin Jud'an melihat kejadian itu.\nApabila Hamzah bin Abdul Muttalib pulang dari memburu dengan busur di bahunya, wanita itu menceritakan apa yang berlaku. Hamzah, yang terkenal gagah dan dihormati, terus ke Masjidil Haram dan memukul kepala Abu Jahal dengan busurnya sambil berkata: “Engkau menghinanya sedangkan aku mengikut agamanya?”\nPada mulanya kata-kata itu lahir daripada marah dan rasa kekeluargaan. Kemudian Allah membuka hatinya dan beliau memeluk Islam dengan sepenuh jiwa. Keislamannya menguatkan orang Islam, dan Quraisy mula berhati-hati.",
   "One day Abu Jahl insulted and harmed the Prophet ﷺ near Mount Safa. He did not answer back. A servant woman of 'Abdullah ibn Jud'an saw what happened.\nWhen Hamzah ibn 'Abdul-Muttalib came back from hunting with his bow on his shoulder, she told him. Hamzah, known for his strength and standing, went straight to the Sacred Masjid and struck Abu Jahl on the head with his bow, saying: “You insult him when I follow his religion?”\nAt first the words came from anger and family pride. Then Allah opened his heart and he accepted Islam wholeheartedly. His Islam strengthened the Muslims, and Quraysh began to tread carefully."],
 k:["Hamzah ialah bapa saudara Nabi ﷺ yang gagah dan berani. Apabila beliau mendengar seseorang menyakiti Nabi ﷺ, beliau membela Baginda. Tidak lama kemudian Hamzah memeluk Islam, dan orang Islam berasa lebih kuat.","Hamzah was the Prophet's ﷺ strong and brave uncle. When he heard someone had hurt the Prophet ﷺ, he stood up for him. Soon after, Hamzah became a Muslim, and the Muslims felt stronger."],
 l:[["Kesabaran Rasulullah ﷺ membuka jalan kepada hidayah orang lain.","The Prophet's ﷺ patience opened the way to guidance for others."],["Allah boleh mengubah sesuatu yang bermula daripada emosi menjadi iman.","Allah can turn what began as emotion into faith."]],
 p:["hamzah","abujahal"],s:"The Conversion of Hamzah, p.52|"},

{id:"s41",n:41,e:4,m:1,y:616.96,age:46,pl:"makkah",sc:"arqam",
 w:["Zulhijjah, tahun ke-6 kenabian, tiga hari selepas Hamzah","Dhul-Hijjah, year 6 of prophethood, three days after Hamzah"],
 t:["Umar al-Khattab memeluk Islam","'Umar accepts Islam"],
 f:["Rasulullah ﷺ pernah berdoa agar Allah memuliakan Islam dengan salah seorang daripada dua lelaki yang lebih dicintai-Nya: Umar al-Khattab atau Abu Jahal.\nSuatu hari Umar keluar dengan pedang terhunus, berniat membunuh Rasulullah ﷺ. Di jalan, seseorang memberitahunya bahawa adiknya Fatimah dan suaminya Sa'id bin Zaid sudah memeluk Islam. Umar terus ke rumah mereka, yang sedang belajar Surah Taha bersama Khabbab. Dalam marahnya beliau memukul adiknya hingga berdarah. Melihat darah itu, hatinya lembut. Beliau meminta lembaran itu, membersihkan diri, lalu membaca permulaan Surah Taha. Beliau berkata: “Alangkah indah dan mulianya kata-kata ini.”\nUmar pergi ke Dar al-Arqam dan mengucap syahadah di hadapan Rasulullah ﷺ. Para sahabat bertakbir dengan kuat. Selepas itu orang Islam mula bersolat secara terbuka di Kaabah. Umar digelar al-Faruq, pembeza antara yang benar dan yang batil.",
   "The Prophet ﷺ had prayed that Allah strengthen Islam through whichever of two men He loved more: 'Umar ibn al-Khattab or Abu Jahl.\nOne day 'Umar went out with a drawn sword, meaning to kill the Prophet ﷺ. On the way someone told him that his sister Fatimah and her husband Sa'id ibn Zayd had become Muslims. 'Umar went straight to their house, where they were learning Surah Taha with Khabbab. In his anger he struck his sister until she bled. Seeing the blood, his heart softened. He asked for the page, cleaned himself and read the opening of Surah Taha. He said: “How beautiful and noble these words are.”\n'Umar went to the House of al-Arqam and declared his faith before the Prophet ﷺ. The companions cried “Allahu akbar” so loudly it was heard far away. After this the Muslims began to pray openly at the Kaabah. 'Umar was called al-Faruq, the one who separates truth from falsehood."],
 k:["Umar seorang lelaki yang sangat kuat. Pada mulanya beliau marah kepada Islam. Tetapi apabila beliau membaca ayat al-Quran dari Surah Taha, hatinya menjadi lembut dan beliau memeluk Islam. Selepas itu orang Islam berani bersolat di Kaabah.","'Umar was a very strong man. At first he was angry with Islam. But when he read verses of the Quran from Surah Taha, his heart softened and he became a Muslim. After that, the Muslims dared to pray at the Kaabah."],
 l:[["Doa boleh mengubah hati manusia.","Prayer can change people's hearts."],["Al-Quran mampu melembutkan hati yang paling keras.","The Quran can soften the hardest heart."]],
 ay:[{r:"Taha 20:1-2",ar:"طه ۝ مَا أَنزَلْنَا عَلَيْكَ الْقُرْآنَ لِتَشْقَىٰ",m:["Taha. Kami tidak menurunkan al-Quran kepadamu supaya engkau menjadi susah.","Ta Ha. We did not send down the Quran to you to cause you distress."]}],
 hd:[{r:"Jami' at-Tirmidhi 3681",m:["Baginda berdoa: “Ya Allah, muliakanlah Islam dengan salah seorang daripada dua lelaki ini yang lebih Engkau cintai: Abu Jahal atau Umar bin al-Khattab.”","He prayed: “O Allah, strengthen Islam with whichever of these two men is dearer to You: Abu Jahl or 'Umar ibn al-Khattab.”"]},{r:"Sahih al-Bukhari 3684",m:["Ibn Mas'ud (r.a.) berkata: “Kami sentiasa mulia sejak Umar memeluk Islam.”","Ibn Mas'ud (r.a.) said: “We have been strong ever since 'Umar accepted Islam.”"]}],
 p:["umar","hamzah","arqam"],s:"The Conversion of 'Umar, p.52|"},

{id:"s42",n:42,e:4,y:617,age:46,pl:"makkah",sc:"kaabah",
 w:["Tahun ke-6 kenabian","Year 6 of prophethood"],
 t:["Tawaran Utbah bin Rabi'ah","'Utbah's offer"],
 f:["Selepas Hamzah dan Umar memeluk Islam, Quraisy menghantar Utbah bin Rabi'ah, seorang pembesar yang bijak berbicara, untuk berunding. Utbah menawarkan harta sehingga Baginda menjadi orang terkaya, kepimpinan, malah takhta kerajaan. Jika Baginda sakit, mereka akan mencari tabib untuk mengubatinya.\nSelepas Utbah selesai, Rasulullah ﷺ bertanya: “Sudahkah engkau selesai, wahai Abu al-Walid? Dengarlah sekarang.” Baginda membaca Surah Fussilat hingga ke ayat sajdah, lalu sujud. Utbah pulang kepada kaumnya dengan wajah yang berubah dan berkata: “Aku telah mendengar kata-kata yang belum pernah aku dengar. Ia bukan syair, bukan sihir dan bukan tilikan. Biarkanlah dia.”",
   "After Hamzah and 'Umar became Muslims, Quraysh sent 'Utbah ibn Rabi'ah, a well-spoken chief, to negotiate. 'Utbah offered wealth until he would be the richest of them, leadership, even a throne. If he was ill, they would find physicians to cure him.\nWhen 'Utbah had finished, the Prophet ﷺ asked: “Have you finished, Abu al-Walid? Now listen.” He recited Surah Fussilat up to the verse of prostration, then prostrated. 'Utbah went back to his people with a changed face and said: “I have heard words like nothing I have heard before. It is not poetry, nor magic, nor soothsaying. Leave him alone.”"],
 l:[["Dengarlah dahulu hingga habis, kemudian jawablah dengan tenang.","Listen until the other person has finished, then answer calmly."],["Dunia tidak dapat membeli risalah.","The world cannot buy the message."]],
 ay:[{r:"Fussilat 41:1-3",ar:"حم ۝ تَنزِيلٌ مِّنَ الرَّحْمَٰنِ الرَّحِيمِ ۝ كِتَابٌ فُصِّلَتْ آيَاتُهُ قُرْآنًا عَرَبِيًّا لِّقَوْمٍ يَعْلَمُونَ",m:["Ha Mim. Diturunkan daripada Tuhan Yang Maha Pemurah lagi Maha Penyayang. Sebuah kitab yang dijelaskan ayat-ayatnya, bacaan dalam bahasa Arab untuk kaum yang mengetahui.","Ha Mim. A revelation from the Most Merciful, the Most Compassionate. A Book whose verses are made clear, a Quran in Arabic for people who know."]}],
 p:["utbah"],s:"Quraish's Representative Negotiates, p.52|"},

{id:"s43",n:43,e:4,m:1,y:617.1,age:"47–49",pl:"makkah",sc:"valley",
 w:["Muharram, tahun ke-7 hingga tahun ke-10 kenabian (617 hingga 619)","Muharram, year 7 to year 10 of prophethood (617 to 619)"],
 t:["Pemulauan di Syi'b Abi Talib","The boycott in the valley of Abu Talib"],
 f:["Apabila Bani Hasyim dan Bani Muttalib tetap melindungi Rasulullah ﷺ, Quraisy berkumpul di Khaif Bani Kinanah dan menulis satu piagam. Mereka tidak akan berkahwin, berjual beli, bergaul atau menerima perdamaian dengan kedua-dua puak itu sehingga Muhammad ﷺ diserahkan untuk dibunuh. Piagam itu digantung di dalam Kaabah.\nBani Hasyim dan Bani Muttalib, yang beriman dan yang tidak, kecuali Abu Lahab, berundur ke Syi'b Abi Talib, sebuah lembah sempit. Bekalan makanan disekat. Mereka terpaksa makan daun dan kulit, dan tangisan kanak-kanak yang lapar kedengaran dari luar. Sesekali ada yang menyeludup makanan, seperti Hakim bin Hizam untuk ibu saudaranya, Khadijah.\nPemulauan ini berlarutan kira-kira tiga tahun.",
   "When Banu Hashim and Banu al-Muttalib kept protecting the Prophet ﷺ, Quraysh met at Khayf Bani Kinanah and wrote a pact. They would not marry, trade, mix or make peace with the two clans until Muhammad ﷺ was handed over to be killed. The pact was hung inside the Kaabah.\nBanu Hashim and Banu al-Muttalib, believers and non-believers alike, except Abu Lahab, withdrew to the Shi'b of Abu Talib, a narrow valley. Food was cut off. They were forced to eat leaves and skins, and the cries of hungry children could be heard from outside. Now and then someone smuggled food in, like Hakim ibn Hizam for his aunt Khadijah.\nThe boycott lasted about three years."],
 k:["Pembesar Quraisy berjanji tidak mahu berjual beli dengan keluarga Nabi ﷺ. Selama tiga tahun keluarga Baginda tinggal di sebuah lembah sempit dengan makanan yang sangat sedikit. Mereka tetap bersabar dan tidak berputus asa.","The leaders of Quraysh agreed not to trade with the Prophet's ﷺ family. For three years his family lived in a narrow valley with very little food. They stayed patient and never gave up."],
 l:[["Kesetiaan keluarga boleh menjadi perlindungan walaupun berbeza akidah.","Family loyalty can protect, even across belief."],["Sabar dalam kelaparan ialah ujian iman yang besar.","Patience in hunger is a great test of faith."]],
 p:["abutalib","khadijah","abulahab"],s:"General Social Boycott, p.52|Pemboikotan ramai; Tiga tahun di lorong Abu Talib"},

{id:"s44",n:44,e:4,y:619.1,age:49,pl:"makkah",sc:"scroll",
 w:["Tahun ke-10 kenabian (619)","Year 10 of prophethood (619)"],
 t:["Piagam pemulauan dimakan anai-anai","The boycott pact is eaten by termites"],
 f:["Ramai penduduk Makkah sendiri tidak senang dengan kezaliman pemulauan itu. Hisham bin Amr mengumpulkan beberapa orang: Zuhair bin Abi Umayyah, al-Mut'im bin 'Adi, Abu al-Bakhtari dan Zam'ah bin al-Aswad. Mereka bersepakat untuk membatalkan piagam itu.\nPada masa yang sama, Rasulullah ﷺ memberitahu Abu Talib bahawa Allah telah menghantar anai-anai memakan piagam itu, kecuali bahagian yang tertulis nama Allah. Abu Talib menyampaikannya kepada Quraisy. Apabila piagam itu diturunkan, ternyata ia seperti yang dikhabarkan: hanya kalimah ‘Bismika Allahumma’ yang tinggal.\nWalaupun Abu Jahal membantah, al-Mut'im mengoyakkan piagam itu. Pemulauan pun berakhir, dan Bani Hasyim keluar dari lembah itu.",
   "Many people of Makkah were themselves uneasy with the cruelty of the boycott. Hisham ibn 'Amr gathered a few men: Zuhayr ibn Abi Umayyah, al-Mut'im ibn 'Adi, Abu al-Bakhtari and Zam'ah ibn al-Aswad. They agreed to undo the pact.\nAt the same time, the Prophet ﷺ told Abu Talib that Allah had sent termites to eat the pact, except where the name of Allah was written. Abu Talib told Quraysh. When the pact was taken down, it was just as he had said: only the words ‘Bismika Allahumma’ (In Your name, O Allah) were left.\nDespite Abu Jahl's protests, al-Mut'im tore up the pact. The boycott ended, and Banu Hashim came out of the valley."],
 l:[["Allah memelihara nama-Nya dan membatalkan kezaliman.","Allah preserves His name and brings injustice to nothing."],["Orang yang adil boleh ditemui walaupun dalam kalangan yang belum beriman.","Fair-minded people can be found even among those who have not yet believed."]],
 p:["abutalib","mutim","abujahal"],s:"A Pact of Injustice and Aggression, p.52|Pelanggaran piagam"}
);
